window.ScripturaLexicons.BDAG_PART_0136 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epera-bdag\" data-source=\"BDAG\" data-search=\"ἐπῆρα epêra forma verbal; remissão ver ἐπαίρω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπῆρα</td><td>forma verbal; remissão</td><td>ver ἐπαίρω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epereazo-bdag\" data-source=\"BDAG\" data-search=\"ἐπηρεάζω epēreázō verbo ameaçar; maltratar; injuriar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπηρεάζω</td><td>verbo</td><td>ameaçar; maltratar; injuriar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epereia-bdag\" data-source=\"BDAG\" data-search=\"ἐπήρεια, ας, ἡ epḗreia substantivo feminino abuso; maus-tratos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπήρεια, ας, ἡ</td><td>substantivo feminino</td><td>abuso; maus-tratos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eperthen-bdag\" data-source=\"BDAG\" data-search=\"ἐπήρθην epḗrthēn forma verbal; remissão ver ἐπαίρω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπήρθην</td><td>forma verbal; remissão</td><td>ver ἐπαίρω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epi-bdag\" data-source=\"BDAG\" data-search=\"ἐπί epí preposição sobre; em; junto a; para; perante; contra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπί</td><td>preposição</td><td>sobre; em; junto a; para; perante; contra</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epibaino-bdag\" data-source=\"BDAG\" data-search=\"ἐπιβαίνω epibaínō verbo subir a; embarcar; pôr os pés em BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιβαίνω</td><td>verbo</td><td>subir a; embarcar; pôr os pés em</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epiballo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιβάλλω epibállō verbo lançar sobre; impor; empreender BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιβάλλω</td><td>verbo</td><td>lançar sobre; impor; empreender</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epibareo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιβαρέω epibaréō verbo sobrecarregar; ser pesado para BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιβαρέω</td><td>verbo</td><td>sobrecarregar; ser pesado para</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epibibazo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιβιβάζω epibibázō verbo fazer subir; pôr sobre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιβιβάζω</td><td>verbo</td><td>fazer subir; pôr sobre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epiblepo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιβλέπω epiblépō verbo olhar atentamente; mostrar consideração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιβλέπω</td><td>verbo</td><td>olhar atentamente; mostrar consideração</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epiblema-bdag\" data-source=\"BDAG\" data-search=\"ἐπίβλημα, ατος, τό epíblēma substantivo neutro remendo; pedaço de tecido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπίβλημα, ατος, τό</td><td>substantivo neutro</td><td>remendo; pedaço de tecido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epiboao-bdag\" data-source=\"BDAG\" data-search=\"ἐπιβοάω epiboáō verbo gritar; clamar em voz alta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιβοάω</td><td>verbo</td><td>gritar; clamar em voz alta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epiboule-bdag\" data-source=\"BDAG\" data-search=\"ἐπιβουλή, ῆς, ἡ epiboulḗ substantivo feminino conspiração; trama BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιβουλή, ῆς, ἡ</td><td>substantivo feminino</td><td>conspiração; trama</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epigambreuo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιγαμβρεύω epigambreúō verbo casar-se como parente próximo; cumprir levirato BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιγαμβρεύω</td><td>verbo</td><td>casar-se como parente próximo; cumprir levirato</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epigeios-bdag\" data-source=\"BDAG\" data-search=\"ἐπίγειος, ον epígeios adjetivo; substantivado terrestre; terreno; mundano BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπίγειος, ον</td><td>adjetivo; substantivado</td><td>terrestre; terreno; mundano</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epigelao-bdag\" data-source=\"BDAG\" data-search=\"ἐπιγελάω epigeláō verbo rir de; escarnecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιγελάω</td><td>verbo</td><td>rir de; escarnecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epiginomai-bdag\" data-source=\"BDAG\" data-search=\"ἐπιγίνομαι epigínomai verbo sobrevir; acontecer; surgir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιγίνομαι</td><td>verbo</td><td>sobrevir; acontecer; surgir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epiginosko-bdag\" data-source=\"BDAG\" data-search=\"ἐπιγινώσκω epiginṓskō verbo conhecer; reconhecer; compreender BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιγινώσκω</td><td>verbo</td><td>conhecer; reconhecer; compreender</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epignosis-bdag\" data-source=\"BDAG\" data-search=\"ἐπίγνωσις, εως, ἡ epígnōsis substantivo feminino conhecimento; reconhecimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπίγνωσις, εως, ἡ</td><td>substantivo feminino</td><td>conhecimento; reconhecimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epigraphe-bdag\" data-source=\"BDAG\" data-search=\"ἐπιγραφή, ῆς, ἡ epigraphḗ substantivo feminino inscrição; sobrescrito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιγραφή, ῆς, ἡ</td><td>substantivo feminino</td><td>inscrição; sobrescrito</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-epera-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπῆρα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epêra⟧</span><span class=\"separator\">·</span><span>forma verbal; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><b>Remissão.</b> <span class=\"greek\">ἐπῆρα</span>: ver <span class=\"greek\">ἐπαίρω</span>.</p></section></article>\n<article id=\"entry-epereazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπηρεάζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epēreázō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete seguinte; Hdt.+; inscrições, papiros; Philo, Mos. 2, 199, De Jos. 71; Just., A I, 1, 1.) <b>Tratar alguém de maneira desprezível; ameaçar, maltratar, injuriar.</b> Usualmente com dativo (como Ael. Aristid. 23, 28 K.=42 p. 777 D.; PFlor 99, 10 [séculos I/II d.C.]; Jos., Bell. 1, 13); com acusativo <span class=\"greek\">τινά</span> (OGI 484, 26 [século II d.C.]): <span class=\"greek\">περὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐπηρεαζόντων</span> <span class=\"greek\">ὑμᾶς</span>, <i>por aqueles que vos maltratam</i> (em algo que fazem, como PFay 123, 7; PLond II, 157, 4s., p. 255 [século II d.C.?]) <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:28</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:44</a>, variante de leitura (Just., A I, 15, 9). <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀγαθὴν</span> <span class=\"greek\">ἀναστροφήν</span>, <i>difamar/caluniar (vossa) boa conduta</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:16</a>. — Schmidt, Syn. IV 275–78; DELG, s.v. <span class=\"greek\">ἐπήρεια</span>; M-M.</p></section></article>\n<article id=\"entry-epereia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπήρεια, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epḗreia⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete anterior; Thu. e outros; OGI 262, 23s.; 669, 6; BGU 340, 21; PRyl 28, 139; Sym.; Philo, In Flacc. 103; 179; Jos., Ant. 13, 382; 15, 23; Ath.) <b>Abuso, maus-tratos.</b> ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἄρχοντος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">αἰῶνος</span> <span class=\"greek\">τούτου</span>, <i>maus-tratos por parte do príncipe deste século</i>, IMg 1:3 (Lucian, Laps. 1, <span class=\"greek\">δαίμονος</span> <span class=\"greek\">ἐπήρεια</span>; ver Dssm., LO 398, 7 [LAE 454, 7], ἐ. τ. <span class=\"greek\">ἀντικειμένου</span>). — DELG.</p></section></article>\n<article id=\"entry-eperthen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπήρθην</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epḗrthēn⟧</span><span class=\"separator\">·</span><span>forma verbal; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><b>Remissão.</b> <span class=\"greek\">ἐπήρθην</span>: ver <span class=\"greek\">ἐπαίρω</span>.</p></section></article>\n<article id=\"entry-epi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπί</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epí⟧</span><span class=\"separator\">·</span><span>preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><b><span class=\"greek\">ἐπί</span></b>, preposição com genitivo, dativo ou acusativo; ver a bibliografia no início de <span class=\"greek\">ἀνά</span> (Hom.+). A ideia básica é «sobre» (em oposição a <span class=\"greek\">ὑπό</span>), Kühner-G. I 495; ver também Rob 600–605. Nas classificações seguintes, os usos dos casos são apresentados sucessivamente; em edições anteriores deste léxico, todas as seções, exceto 13, 17 e 18 (de tempo), eram incluídas sob a rubrica geral «Lugar».</p>\n<p class=\"entry-text\"><b>① Marcador de localização ou superfície, respondendo à pergunta «onde?»; em, sobre, perto de.</b> <b>ⓐ Com genitivo</b>, assinalando posição sobre uma superfície: ἐ. (<span class=\"greek\">τῆς</span>) <span class=\"greek\">γῆς</span>, <i>na terra</i> (cf. En 9:1; 98:1; ἐ. <span class=\"greek\">γῆς</span> 25:6; PsSol 17:2), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:10</a>, 19; 9:6; 23:9; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:47</a> e outros (Ar. 12, 1; Just., A I, 54, 7 e outros). ἐ. <span class=\"greek\">τῆς</span> <span class=\"greek\">θαλάσσης</span>, <i>sobre o mar</i> (cf. Job 9:8; Dio Chrys. 10 [11], 129, <span class=\"greek\">βαδίζειν</span> ἐ. <span class=\"greek\">τῆς</span> <span class=\"greek\">θαλ</span>.; Lucian, Philops. 13, <span class=\"greek\">βαδίζειν</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὕδατος</span>, VH 2, 4; Artem. 3, 16, ἐ. τ. <span class=\"greek\">θαλάσσης</span> <span class=\"greek\">περιπατεῖν</span>; escólio a Nicander, Ther. 15 p. 5, 26ss., com apoio no testemunho de Hesíodo: Órion recebeu dos deuses um dom [<span class=\"greek\">δωρεά</span>], <span class=\"greek\">καὶ</span> ἐ. <span class=\"greek\">κυμάτων</span> <span class=\"greek\">πορεύεσθαι</span> <span class=\"greek\">καὶ</span> ἐ. <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:26</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:48s</a>.; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:19</a> (com acusativo em P75; ver 4bβ adiante). ἐ. <span class=\"greek\">τῶν</span> <span class=\"greek\">νεφελῶν</span>, <i>sobre as nuvens</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:30</a>; 26:64 (Da 7:13; cf. Philo, Praem. 8). ἐ. <span class=\"greek\">κλίνης</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:2</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:34</a>. ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">δώματος</span>, <i>sobre o telhado</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:31</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:17</a>; 10:27, seguido de plural.</p>\n<p class=\"entry-text\">Com verbos: <span class=\"greek\">κάθημαι</span> ἐ. <span class=\"greek\">τινος</span>, <i>sentar-se sobre alguma coisa</i> (Job 2:8; ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἅρματος</span>, GrBar 6:2; cf. JosAs 27:1, ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀχήματος</span> <span class=\"greek\">καθεζόμενος</span>; Just., D. 90, 5, ἐ. <span class=\"greek\">λίθου</span> <span class=\"greek\">καθεζόμενος</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:3</a>; 27:19; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:28</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:16</a>; 9:17 (a mesma preposição é usada em Apocalipse com <span class=\"greek\">κάθημαι</span> e dativo; ver bα adiante; e com acusativo, cα). <span class=\"greek\">ἑστηκέναι</span> ἐ. <span class=\"greek\">τινος</span>, <i>estar de pé sobre alguma coisa</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:40</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:5</a>, 8 (Just., D. 86, 2, <span class=\"greek\">ἐστηρίχθαι</span>). Com partes do corpo: ἐ. <span class=\"greek\">χειρῶν</span> <span class=\"greek\">αἴρειν</span>, <i>carregar nas mãos</i> (isto é, com as mãos), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:6</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:11</a> (ambos Ps 90:12). ἐ. <span class=\"greek\">κεφαλῆς</span>, <i>sobre a cabeça</i> (Hdt. 5, 12, 4), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:7</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:10</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:1</a>. ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">μετώπου</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:3</a>; 9:4. ἐ. <span class=\"greek\">γυμνοῦ</span>, <i>sobre o corpo nu</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:51</a>. Cf. o uso de <span class=\"greek\">ἐπί</span> com <span class=\"greek\">καθίζω</span> e genitivo e de <span class=\"greek\">ἐπί</span> com <span class=\"greek\">κάθημαι</span> e acusativo em <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:28</a>. — Em sentido geral e figurado, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:23</a>.</p>\n<p class=\"entry-text\"><b>ⓑ Com dativo</b>, em geral sugerindo contiguidade: <i>sobre, em, acima de</i>. <b>α. Respondendo à pergunta «onde?»</b> (Hom. e outros; inscrições, papiros, LXX; Just., D. 105, 5, ἐ. <span class=\"greek\">τῷ</span> <span class=\"greek\">σταυρῷ</span>; Tat. 9:1, ἐ. <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὄρεσι</span>; Ath. 20, 1, ἐ. <span class=\"greek\">τῷ</span> <span class=\"greek\">μετώπῳ</span>; Mel., P. 19, 131, ἐ. <span class=\"greek\">σάκκῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σποδῷ</span>): ἐ. <span class=\"greek\">πίνακι</span>, <i>numa bandeja</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:8</a>, 11; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:25</a>, 28. <span class=\"greek\">ἀνακλῖναι</span> ἐ. <span class=\"greek\">τῷ</span> <span class=\"greek\">χλωρῷ</span> <span class=\"greek\">χόρτῳ</span>, <i>reclinar-se na relva verde</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:39</a>. ἐ. <span class=\"greek\">τοῖς</span> <span class=\"greek\">κραβάττοις</span>, v. 55. <span class=\"greek\">ἐπέκειτο</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτῷ</span>, <i>estava colocado sobre ela (ou diante dela)</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:38</a>. <span class=\"greek\">καθήμενος</span> ἐ. <span class=\"greek\">τῷ</span> <span class=\"greek\">θρόνῳ</span>, <i>assentado no trono</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:9</a> (cf. genitivo com <span class=\"greek\">καθ</span>. em 1a acima, e acusativo em cα abaixo); 5:13; 7:10 e frequentemente. <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἵπποις</span> <span class=\"greek\">λευκοῖς</span>, <i>sobre cavalos brancos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:14</a>. ἐ. <span class=\"greek\">σανίσιν</span>, <i>sobre tábuas</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.44\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:44</a>. ἐ. <span class=\"greek\">τῇ</span> <span class=\"greek\">στοᾷ</span>, <i>no pórtico</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:11</a>. <span class=\"greek\">τὰ</span> ἐ. <span class=\"greek\">τοῖς</span> <span class=\"greek\">οὐρανοῖς</span>, <i>o que está acima dos céus (ou neles)</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:10</a>. <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτῷ</span>, <i>acima dele, sobre sua cabeça</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:38</a> (=<a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:37</a>, <span class=\"greek\">ἐπάνω</span> τ. <span class=\"greek\">κεφαλῆς</span> <span class=\"greek\">αὐτοῦ</span>).</p>\n<p class=\"entry-text\"><b>β. Respondendo à pergunta «para onde?»; sobre, para cima de</b> (Hom. e outros), com verbos que indicam direção: <span class=\"greek\">οἰκοδομεῖν</span> ἐ. <span class=\"greek\">τινι</span>, <i>edificar sobre alguma coisa</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:18</a>. <span class=\"greek\">ἐποικοδομεῖν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:20</a>. <span class=\"greek\">ἐπιβάλλειν</span> <span class=\"greek\">ἐπίβλημα</span> ἐ. <span class=\"greek\">ἱματίῳ</span> <span class=\"greek\">παλαιῷ</span>, <i>pôr remendo sobre uma veste velha</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:16</a>. <span class=\"greek\">ἐπιπίπτειν</span> ἐ. <span class=\"greek\">τινι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:16</a>. <span class=\"greek\">ἐκάθισεν</span> ἐ. <span class=\"greek\">τῷ</span> <span class=\"greek\">θρόνῳ</span>, <i>sentou-se no trono</i>, GJs 11:1. <span class=\"greek\">λίθον</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">βαλέτω</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:7</a>, variante (cf. 12a abaixo).</p>\n<p class=\"entry-text\"><b>ⓒ Com acusativo</b>, respondendo à pergunta «onde?» (Hom. e outros; LXX; JosAs 29:2, <span class=\"greek\">φορῶν</span> ἐ. <span class=\"greek\">τὸν</span> <span class=\"greek\">μηρὸν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ῥομφαίαν</span>; Just., D. 53, 1, <span class=\"greek\">ζυγὸν</span> ἐ. <span class=\"greek\">αὐχένα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἔχων</span>). <b>α. Em cima de, sobre alguma coisa.</b> <span class=\"greek\">καθεύδειν</span> ἐ. <span class=\"greek\">τι</span>, <i>dormir sobre algo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:38</a>; <span class=\"greek\">καθῆσθαι</span> ἐ. <span class=\"greek\">τι</span>, <i>sentar-se sobre algo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:28</a> (no mesmo versículo <span class=\"greek\">καθίζω</span> com genitivo; ver a acima), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:15</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:4</a>; 6:2; 11:16 e outros; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:35b</a>. <span class=\"greek\">κεῖσθαι</span> ἐ. <span class=\"greek\">τι</span>, <i>jazer sobre algo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:15</a>. <span class=\"greek\">κατακεῖσθαι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:25</a>. <span class=\"greek\">ἑστηκέναι</span> ἐ. <span class=\"greek\">τὸν</span> <span class=\"greek\">αἰγιαλόν</span>, <i>estar em pé na praia</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:2</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:1</a>. <span class=\"greek\">ἑστῶτας</span> ἐ. <span class=\"greek\">τὴν</span> <span class=\"greek\">θάλασσαν</span>, <i>de pé junto ao mar</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 15:2</a>. <span class=\"greek\">ἔστη</span> ἐ. <span class=\"greek\">τὴν</span> <span class=\"greek\">κεφαλὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παιδίου</span>, <i>(a estrela) permaneceu imóvel sobre a cabeça da criança</i>, GJs 21:3. <span class=\"greek\">σκηνοῦν</span> ἐ. <span class=\"greek\">τινα</span>, <i>estender uma tenda sobre alguém</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:15</a>. ἐ. <span class=\"greek\">τὴν</span> <span class=\"greek\">δεξιάν</span>, <i>à direita</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:1</a>. <span class=\"greek\">λίθος</span> ἐ. <span class=\"greek\">λίθον</span>, <i>pedra sobre pedra</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:2</a>.</p>\n<p class=\"entry-text\"><b>β. ἐ. <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτό</span>, no mesmo lugar, juntos</b> (Ps.-X., Respublica Athen. [The Old Oligarch] 2, 2; Pla., Rep. 329a; SIG 736, 66 [92 a.C.]. Nos papiros, também «ao todo»: PTebt 14, 20 [114 a.C.]; PFay 102, 6. — 2 Km 2:13; En 100:2). <span class=\"greek\">εἶναι</span> ἐ. <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτό</span>, <i>estar juntos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:35</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:15</a>; 2:1, 44. Em <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:5</a> trata-se de expressão eufemística para a união sexual. <span class=\"greek\">κατοικεῖν</span> ἐ. <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτό</span>, <i>morar no mesmo lugar</i> (Dt 25:5), Hm 5, 1, 4. Também com verbos de movimento (Sus 14 Theod.): <span class=\"greek\">συνέρχεσθαι</span> ἐ. <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτό</span>, <i>reunir-se no mesmo lugar</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:20</a>; 14:23; cf. B 4:10 (Just., A I, 67, 3, <span class=\"greek\">συνέλευσις</span> <span class=\"greek\">γίνεται</span>); <span class=\"greek\">συνάγεσθαι</span> (Phlegon of Tralles [Hadr.]: 257 Fgm. 36 III 9 Jac.; PsSol 2:2; TestJob 28:5; Jos., Bell. 2, 346), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:34</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:26</a> (Ps 2:2); 1 Cl 34:7. ἐ. <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">μίγνυσθαι</span>, <i>misturar-se uns aos outros</i>, Hm 10, 3, 3. <span class=\"greek\">προσετίθει</span> ἐ. <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτό</span>, <i>acrescentava ao número deles</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.47\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:47</a>.</p>\n<p class=\"entry-text\"><b>γ. Junto de, perto de alguém ou alguma coisa.</b> <span class=\"greek\">καθῆσθαι</span> ἐ. <span class=\"greek\">τὸ</span> <span class=\"greek\">τελώνιον</span>, <i>estar sentado na coletoria de impostos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:9</a> (ἐ. <span class=\"greek\">τὰς</span> <span class=\"greek\">ὡραίας</span> <span class=\"greek\">πύλας</span>, GrBar prol. 2); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:14</a>. <span class=\"greek\">ἑστηκέναι</span> ἐ. <span class=\"greek\">τὴν</span> <span class=\"greek\">θύραν</span>, <i>estar em pé à porta</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:20</a>. <span class=\"greek\">σὺ</span> <span class=\"greek\">ἔστης</span> ἐ. <span class=\"greek\">τὸ</span> <span class=\"greek\">θυσιαστήριον</span>, <i>tu estás de pé, como sacerdote, junto ao altar</i>, GJs 8:2 (<span class=\"greek\">ἕστηκας</span>, deStrycker). <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὑμᾶς</span>, <i>entre vós</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:10</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:21</a>. — A respeito de pessoas sobre as quais se faz algo: <span class=\"greek\">ὀνομάζειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">Ἰησοῦ</span> ἐ. <span class=\"greek\">τινα</span>, <i>pronunciar o nome de Jesus sobre alguém</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:13</a>. <span class=\"greek\">ἐπικαλεῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομά</span> <span class=\"greek\">τινος</span> ἐ. <span class=\"greek\">τινα</span>, <i>reivindicar alguém como pertencente a si</i> (Jer 14:9; 2 Ch 7:14; 2 Macc 8:15), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:17</a> (Am 9:12); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:7</a>; Hs 8, 6, 4. <span class=\"greek\">προσεύχεσθαι</span> ἐ. <span class=\"greek\">τινα</span>, <i>orar sobre alguém</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:14</a>.</p>\n<p class=\"entry-text\"><b>② Marcador de presença ou ocorrência perto de objeto ou área; junto a, perto de.</b> <b>ⓐ Com genitivo</b>, de proximidade imediata a coisas (Hdt. 7, 115; X., An. 4, 3, 28 e outros; LXX, Just.): ἐ. τ. <span class=\"greek\">θυρῶν</span>, <i>às portas</i> (Plut., C. Gracch. 841 [14, 3]; PRyl 127, 8s. [29 d.C.], <span class=\"greek\">κοιμωμένου</span> <span class=\"greek\">μου</span> ἐ. <span class=\"greek\">τῆς</span> <span class=\"greek\">θύρας</span>; 1 Macc 1:55; Just., D. 111, 4), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:23</a> (ver b abaixo para o dativo em 5:9). ἐ. <span class=\"greek\">τῆς</span> <span class=\"greek\">θαλάσσης</span>, <i>perto do mar</i> (Polyb. 1, 44, 4; Ex 14:2; Dt 1:40; 1 Macc 14:34), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:1</a>. ἐ. <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδοῦ</span>, <i>à beira da estrada</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:19</a>. <span class=\"greek\">ἐσθίειν</span> ἐ. <span class=\"greek\">τῆς</span> <span class=\"greek\">πραπέζης</span> <span class=\"greek\">τινός</span>, <i>comer à mesa de alguém</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:30</a> (cf. POxy 99, 14 [55 d.C.], <span class=\"greek\">τράπεζα</span>, <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἧς</span> <span class=\"greek\">Σαραπίων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μέτοχοι</span>; Da 11:27 LXX, ἐ. <span class=\"greek\">μιᾶς</span> <span class=\"greek\">τραπέζης</span>). ἐ. <span class=\"greek\">τοῦ</span> (<span class=\"greek\">τῆς</span>) <span class=\"greek\">βάτου</span>, <i>na sarça</i> = na passagem a respeito da sarça (isto é, Ex 3:1ss.), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:26</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:37</a>.</p>\n<p class=\"entry-text\"><b>ⓑ Com dativo</b>, de proximidade imediata, <i>junto a, perto de</i> (Hom.+): <span class=\"greek\">ἦν</span> <span class=\"greek\">ἔτι</span> ἐ. <span class=\"greek\">τῷ</span> <span class=\"greek\">τόπῳ</span> <span class=\"greek\">ὅπου</span>, <i>ainda estava no lugar em que</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:30</a>, variante (em lugar de <span class=\"greek\">ἐν</span>; cf. Just., D. 402). ἐ. <span class=\"greek\">τῇ</span> <span class=\"greek\">θύρᾳ</span> (ἐ. <span class=\"greek\">θύραις</span>), <i>à porta</i> (Hom. e outros; Wsd 19:17; Jos., Ant. 17, 90; Just., D. 32, 3), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:33</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:29</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:9</a> (ver a acima). ἐ. <span class=\"greek\">τοῖς</span> <span class=\"greek\">πυλῶσιν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:12</a>. ἐ. <span class=\"greek\">τῇ</span> <span class=\"greek\">πηγῇ</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:6</a> (Jos., Ant. 5, 58, ἐ. <span class=\"greek\">τινι</span> <span class=\"greek\">πηγῇ</span>; Just., A I, 64, 1, ἐ. <span class=\"greek\">ταῖς</span> … <span class=\"greek\">πηγαῖς</span>). ἐ. <span class=\"greek\">τῇ</span> <span class=\"greek\">προβατικῇ</span> (subentendido <span class=\"greek\">πύλῃ</span>), <i>perto da porta das ovelhas</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:2</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:10</a>. ἐ. <span class=\"greek\">τῷ</span> <span class=\"greek\">ποταμῷ</span>, <i>junto ao rio</i> (desde Il. 7, 133; Jos., Ant. 4, 176, ἐ. τ. <span class=\"greek\">Ἰορδάνῳ</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:14</a>. — Acerca de pessoas (Diod S 14, 113, 6; Just., A I, 40, 7): <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὑμῖν</span>, <i>entre vós</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:7</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:14</a>, variante.</p>\n<p class=\"entry-text\"><b>③ Marcador de participação em procedimento oficial; perante, diante de</b>, com genitivo de pessoa, sobretudo na linguagem processual (Pla., Leg. 12, 943d; Isaeus 5, 1 e outros; UPZ 71, 15; 16 [152 a.C.]; POxy 38, 11; Mitt-Wilck. I/2, 382, 23 = BGU 909, 23; Jos., Vi. 258; Just., A II, 1, 1, ἐ. <span class=\"greek\">Οὐρβίκου</span>). ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἡγεμόνος</span>, <i>na presença do governador</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:14</a>. ἐ. <span class=\"greek\">ἡγεμόνων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">βασιλέων</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:9</a>. ἐ. <span class=\"greek\">σου</span>, <i>perante ti</i> (o procurador), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:30</a>. ἐ. <span class=\"greek\">Τερτούλλου</span>, subscrição de Phlm, variante; <span class=\"greek\">στάντος</span> <span class=\"greek\">μου</span> ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">συνεδρίου</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:20</a> (cf. Diod S 11, 55, 4, ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κοινοῦ</span> <span class=\"greek\">συνεδρίου</span> τ. <span class=\"greek\">Ἑλλήνων</span>). <span class=\"greek\">γυναικὸς</span> … <span class=\"greek\">διαβληθείσης</span> ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, Papias (2:17). <span class=\"greek\">κρίνεσθαι</span> ἐ. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀδίκων</span>, <i>litigar diante dos injustos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:1</a>. <span class=\"greek\">κριθήσεται</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὑμῶν</span>, <i>será julgado perante vosso tribunal</i>, D 11:11. <span class=\"greek\">μαρτυρεῖν</span> ἐ. <span class=\"greek\">Ποντίου</span> <span class=\"greek\">Πιλάτου</span>, <i>testemunhar perante Pôncio Pilatos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:13</a> (ver <span class=\"greek\">μαρτυρέω</span> 1c). ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">βήματος</span> (POxy 37 I, 3 [49 d.C.]), <span class=\"greek\">ἑστὼς</span> ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">βήματος</span> <span class=\"greek\">Καίσαρός</span> <span class=\"greek\">εἰμι</span>, <i>estou diante do tribunal de César</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:10</a> (Ápiano diz, a respeito de si mesmo, Prooem. c. 15 §62, <span class=\"greek\">δίκαις</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Ῥώμῃ</span> <span class=\"greek\">συναγορεύσας</span> ἐ. <span class=\"greek\">τῶν</span> <span class=\"greek\">βασιλέων</span> = «atuei como advogado em processos em Roma perante os imperadores»). — Em sentido geral, <i>na presença de alguém</i> (Appian, Syr. 61 §324, <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὑμῶν</span> = «em vossa presença»): ἐ. <span class=\"greek\">Τίτου</span>, <i>perante Tito</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:14</a>. Cf. ⑩ adiante.</p>\n<p class=\"entry-text\"><b>④ Marcador de movimento rumo a um objetivo ou de contato com ele; para, em direção a, sobre.</b> <b>ⓐ Com genitivo</b>, indicando contato com o alvo alcançado, respondendo à pergunta «para onde?»; <i>em direção a, sobre, em</i> com verbos de movimento (Appian, Iber. 98 §427, <span class=\"greek\">ἀπέπλευσεν</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">οἴκου</span> = «navegou [em direção à] casa»; PGM 4, 2468s., <span class=\"greek\">ἀναβὰς</span> ἐ. <span class=\"greek\">δώματος</span>; JosAs 27:1, <span class=\"greek\">ἀνέδραμε</span> … ἐ. <span class=\"greek\">πέτρας</span>; Jos., Ant. 4, 91, <span class=\"greek\">ἔφευγον</span> ἐ. τ. <span class=\"greek\">πόλεων</span>; Tat. 33:3, <span class=\"greek\">Εὐρώπην</span> ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ταύρου</span> <span class=\"greek\">καθιδρύσαντος</span>): <span class=\"greek\">βάλλειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">σπόρον</span> ἐ. <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:26</a>; também <span class=\"greek\">σπείρειν</span>, v. 31; <span class=\"greek\">πίπτειν</span> (Wsd 18:23; TestAbr A 3 p. 80, 11 [Stone p. 8]; JosAs 9:1), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:20</a>; 14:35; <span class=\"greek\">καθιέναι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:11</a>; <span class=\"greek\">τιθέναι</span> (Sir 17:4), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:16</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:19</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:15</a>; <span class=\"greek\">ἔρχεσθαι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:7</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:10</a>; <span class=\"greek\">γίνεσθαι</span> ἐ., <i>chegar a, encontrar-se em</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:21</a>; <span class=\"greek\">γενόμενος</span> ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">τόπου</span>, <i>quando chegou ao lugar</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:40</a>; <span class=\"greek\">καθίζειν</span>, <i>tomar assento</i>, ἐ. <span class=\"greek\">θρόνου</span>, <i>no trono</i> (JosAs 7:1 e outros), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:28</a> (ver 1a, final); 23:2; 25:31; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:13</a> (ἐ. <span class=\"greek\">βήματος</span>, de Pilatos, como Jos., Bell. 2, 172; de Jesus, Just., A I, 35, 6). <span class=\"greek\">κρεμαννύναι</span> ἐ. <span class=\"greek\">ξύλου</span>, <i>pendurar em um madeiro</i> (isto é, na cruz; Gen 40:19; cf. Just., D. 86, 6, <span class=\"greek\">σταυρωθῆναι</span> ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ξύλου</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:30</a>; 10:39; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:13</a> (Dt 21:23).</p>\n<p class=\"entry-text\"><b>ⓑ Com acusativo.</b> <b>α. Indicação de direção</b> (En 24:2, ἐ. <span class=\"greek\">νότον</span>, «para o sul», da posição de uma montanha), de movimento que toma rumo determinado: <i>para, em direção a</i>. <span class=\"greek\">ἐκτείνας</span> τ. <span class=\"greek\">χεῖρα</span> ἐ. <span class=\"greek\">τοὺς</span> <span class=\"greek\">μαθητάς</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.49\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:49</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:53</a> (JosAs 12:8). <span class=\"greek\">πορεύεσθαι</span> ἐ. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀπολωλός</span>, <i>ir após o que se perdera</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:4</a>. ἐ. <span class=\"greek\">τὴν</span> <span class=\"greek\">῏Ασσον</span>, <i>na direção de Assos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:13</a>. <span class=\"greek\">ἐπιστρέφειν</span> ἐ. <span class=\"greek\">τι</span>, <i>voltar-se para algo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:22</a> (cf. Pr 26:11; En 99:5). <span class=\"greek\">ὡς</span> ἐ. <span class=\"greek\">λῃστήν</span>, <i>como contra um salteador</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:55</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:48</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:52</a>.</p>\n<p class=\"entry-text\"><b>β. De um ponto a outro; através de, sobre</b>, com movimento implícito (Hom.+; LXX): <span class=\"greek\">περιπατεῖν</span>, <span class=\"greek\">ἐλθεῖν</span> ἐ. τ. <span class=\"greek\">θάλασσαν</span> ou ἐ. τ. <span class=\"greek\">ὕδατα</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:25</a>, 28s.; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:19</a> P75. Da propagação por uma região (PsSol 17:10): fome, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:11</a>; 11:28; trevas, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:45</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:44</a>. ἐ. <span class=\"greek\">σταδίους</span> <span class=\"greek\">δώδεκα</span> <span class=\"greek\">χιλιάδων</span>, <i>por doze mil estádios</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:16</a>, variante (Polyaenus 5, 44, 4, ἐ. <span class=\"greek\">στάδια</span> <span class=\"greek\">δέκα</span>); ἐ. <span class=\"greek\">πλεῖον</span>, <i>mais além</i> (1 Esdr 2:24; 2 Macc 10:27), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:17</a>.</p>\n<p class=\"entry-text\"><b>γ. Do alvo atingido; em, sobre alguém ou alguma coisa</b> (Hom. e outros; LXX): <span class=\"greek\">πέσατε</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἡμᾶς</span>, <i>caí sobre nós</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:30</a> (Hos 10:8); <span class=\"greek\">ἔπεσεν</span> ἐ. <span class=\"greek\">τὰ</span> <span class=\"greek\">πετρώδη</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:5</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:4</a>. <span class=\"greek\">ἔρχεσθαι</span> ἐ. <span class=\"greek\">τινα</span>, <i>vir sobre alguém</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:16</a>; também <span class=\"greek\">καταβαίνειν</span>, <i>descer do alto</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:33</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:21</a>. <span class=\"greek\">ἀναβαίνειν</span> (Jos., Ant. 13, 138; Just., A II, 12, 7), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:19</a>. <span class=\"greek\">ἐπιβαίνειν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:5</a> (Zech 9:9). — <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:3</a>; 9:4 e outros. <span class=\"greek\">διασωθῆναι</span> ἐ. τ. <span class=\"greek\">γῆν</span>, <i>ser levado a salvo à terra</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.44\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:44</a>; cf. v. 43; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:27</a>. ἐ. <span class=\"greek\">τὸ</span> <span class=\"greek\">πλοῖον</span>, <i>para o navio</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:13</a>. <span class=\"greek\">ἀναπεσεῖν</span> ἐ. <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span>, <i>deitar-se ou sentar-se no chão</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:35</a>. <span class=\"greek\">ἔρριψεν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">χαμαὶ</span> ἐ. <span class=\"greek\">τὸν</span> <span class=\"greek\">σάκκον</span>, <i>atirou-se ao chão sobre o pano de saco</i>, GJs 13:1. <span class=\"greek\">τιθέναι</span> <span class=\"greek\">τι</span> ἐ. <span class=\"greek\">τι</span>, <i>pôr algo sobre alguma coisa</i> (JosAs 16:11), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:15</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:33</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:25</a>, variante; do mesmo modo <span class=\"greek\">ἐπιτιθέναι</span> (JosAs 29:5), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:4</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:25</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:5</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:6</a>, 15; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:10</a>. <span class=\"greek\">ἐπιβάλλειν</span> τ. <span class=\"greek\">χεῖρας</span> ἐ. <span class=\"greek\">τινα</span> (Gen 22:12 e outros), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:50</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:12</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:18</a>.</p>\n<p class=\"entry-text\">Principalmente depois de verbos que exprimem <i>colocar, deitar, pôr, trazer</i> etc., <i>sobre, para</i>: <span class=\"greek\">ἀναβιβάζω</span>, <span class=\"greek\">ἀναφέρω</span>, <span class=\"greek\">βάλλω</span>, <span class=\"greek\">γράφω</span>, <span class=\"greek\">δίδωμι</span>, <span class=\"greek\">ἐγγίζω</span>, <span class=\"greek\">ἐπιβιβάζω</span>, <span class=\"greek\">ἐπιγράφω</span>, <span class=\"greek\">ἐποικοδομέω</span>, <span class=\"greek\">ἐπιρ</span>(ρ)<span class=\"greek\">ίπτω</span>, <span class=\"greek\">θεμελιόω</span>, <span class=\"greek\">ἵστημι</span>, <span class=\"greek\">κατάγω</span>, <span class=\"greek\">οἰκοδομέω</span>, <span class=\"greek\">σωρεύω</span>; ver esses verbetes. Similarmente, <span class=\"greek\">βρέχειν</span> ἐ. <span class=\"greek\">τινα</span>, <i>fazer a chuva cair sobre alguém</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:45</a> (cf. PsSol 17:18); também τ. <span class=\"greek\">ἥλιον</span> <span class=\"greek\">ἀνατέλλειν</span> ἐ. <span class=\"greek\">τινα</span>, <i>fazer o sol nascer, de modo que seus raios incidam sobre alguém</i>, ibid. <span class=\"greek\">τύπτειν</span> <span class=\"greek\">τινὰ</span> ἐ. <span class=\"greek\">τὴν</span> <span class=\"greek\">σιαγόνα</span>, <i>ferir alguém na face</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:29</a>. <span class=\"greek\">πίπτειν</span> ἐ. (<span class=\"greek\">τὸ</span>) <span class=\"greek\">πρόσωπον</span>, <i>cair sobre o rosto</i> (Jdth 14:6), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:6</a>; 26:39; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:12</a>; 17:16; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:25</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:11</a>. — <i>Para, sobre</i>, com acusativo de coisa: <span class=\"greek\">πορεύεσθαι</span> ἐ. <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδόν</span>, <i>ir à estrada</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:26</a>; cf. 9:11; ἐ. <span class=\"greek\">τὰς</span> <span class=\"greek\">διεξόδους</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:9</a>. <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πνέῃ</span> <span class=\"greek\">ἄνεμος</span> ἐ. <span class=\"greek\">πᾶν</span> <span class=\"greek\">δένδρον</span>, <i>para que nenhum vento sopre sobre árvore alguma</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:1</a>.</p>\n<p class=\"entry-text\"><b>δ. De proximidade a algo ou alguém; a, até, nas cercanias de, junto a.</b> ἐ. <span class=\"greek\">τὸ</span> <span class=\"greek\">μνημεῖον</span>, <i>até o túmulo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:2</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:1</a>, variante, 22, 24; cf. ἐ. <span class=\"greek\">τὸ</span> <span class=\"greek\">μνῆμα</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:2</a>, variante; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:1</a>. <span class=\"greek\">ἔρχεσθαι</span> ἐ. <span class=\"greek\">τι</span> <span class=\"greek\">ὕδωρ</span>, <i>chegar a certa água</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:36</a>; ἐ. <span class=\"greek\">τὴν</span> <span class=\"greek\">πύλην</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σιδηρᾶν</span>, <i>até o portão de ferro</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:10</a>. <span class=\"greek\">καταβαίνειν</span> ἐ. <span class=\"greek\">τὴν</span> <span class=\"greek\">θάλασσαν</span>, <i>descer ao mar</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:16</a>. ἐ. <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰορδάνην</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:13</a> (Just., D. 88, 3 e outros). <span class=\"greek\">ἀναπίπτειν</span> ἐ. <span class=\"greek\">τὸ</span> <span class=\"greek\">στῆθος</span>, <i>reclinar-se sobre o peito (de Jesus)</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:25</a>; 21:20. <span class=\"greek\">πίπτειν</span> ἐ. <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span>, <i>cair aos pés (de alguém)</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:25</a> (JosAs 14:10, <span class=\"greek\">ἔπεσεν</span> ἐ <span class=\"greek\">πρόσωπον</span> ἐ. <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">αὐτοῦ</span>). ἐ. τ. <span class=\"greek\">ἀκάνθας</span>, <i>entre os espinhos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:7</a>. — Com acusativo de pessoa, <i>até alguém</i>: ἐ. <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">ἐλθόντες</span>, <i>vieram até Jesus</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:33</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:27</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:21</a>.</p>\n<p class=\"entry-text\"><b>ε. Em imagem de alvo ou objetivo; a, para</b> (Just., A II, 7, 6, <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἀμφότερα</span> <span class=\"greek\">τρέπεσθαι</span>): <span class=\"greek\">ἐπιστρέφειν</span>, <span class=\"greek\">ἐπιστρέφεσθαι</span> ἐ. <span class=\"greek\">τινα</span>, <i>voltar-se para alguém</i> (Dt 30:10; 31:20 e outros; Ar. 2, 1, <span class=\"greek\">ἔλθωμεν</span> <span class=\"greek\">καὶ</span> ἐ. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀνθρώπινον</span> <span class=\"greek\">γένος</span>, «voltemo-nos agora ao gênero humano»; Just., D. 56, 11, ἐ. <span class=\"greek\">τὰς</span> <span class=\"greek\">γραφὰς</span> <span class=\"greek\">ἐπανελθών</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:17</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:35</a>; 11:21; 14:15; 26:20; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:9</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:25</a>.</p>\n<p class=\"entry-text\"><b>⑤ Marcador de modo, correspondente a advérbio, com dativo</b> (Aeschyl., Suppl. 628, <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἀληθείᾳ</span>; UPZ 162 VI, 3 [117 a.C.], <span class=\"greek\">κακοτρόπως</span> <span class=\"greek\">καὶ</span> ἐ. <span class=\"greek\">ῥαδιουργίᾳ</span>; POxy 237 VI, 21, ἐ. <span class=\"greek\">τῇ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρ</span>. <span class=\"greek\">σωτηρίᾳ</span>; <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὁράσει</span>, En 14:8; Just., A I, 9, 3, <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὕβρει</span>; 55, 7, ἐ. <span class=\"greek\">τούτῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σχήματι</span>, «desta maneira»; Tat. 17, 1, <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἀκριβείᾳ</span>; Ath. 33, 2, <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἑνὶ</span> <span class=\"greek\">γάμῳ</span>): ὁ <span class=\"greek\">σπείρων</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">εὐλογίαις</span> (em oposição a ὁ <span class=\"greek\">σπείρων</span> <span class=\"greek\">φειδομένως</span>, «o que semeia parcimoniosamente»), <i>aquele que semeia generosamente</i> (literalmente, «em bênçãos»), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:6</a>. <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">εὐλογίαις</span> <span class=\"greek\">θερίζειν</span>, <i>colher generosamente</i>, ibid.</p>\n<p class=\"entry-text\"><b>⑥ Marcador da base de um estado de ser, ação ou resultado; sobre, com dativo</b> (Hom. e outros). <b>ⓐ <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἄρτῳ</span> <span class=\"greek\">ζῆν</span></b>, <i>viver de pão</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:4</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:4</a> (ambos Dt 8:3; cf. Ps.-Pla., Alcib. 1, 105c; Plut., Mor. 526d; Alciphron 3, 7, 5; SibOr 4, 154). ἐ. <span class=\"greek\">τῷ</span> <span class=\"greek\">ῥήματί</span> <span class=\"greek\">σου</span>, <i>apoiando-me em tua palavra</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:5</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">συνῆκαν</span> ἐ. <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἄρτοις</span>, <i>não chegaram a compreender (isso) por meio da reflexão sobre (o milagre dos) pães</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.52\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:52</a> (cf. Demosth. 18, 121, <span class=\"greek\">τί</span> <span class=\"greek\">σαυτὸν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐλλεβορίζεις</span> ἐ. <span class=\"greek\">τούτοις</span> [sc. <span class=\"greek\">λόγοις</span>], «por que não procuras compreender essas palavras?»). ἐ. <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span>, <i>com base na fé</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:16</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:9</a>. <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐλπίδι</span>, <i>com base na esperança, apoiando-se na esperança</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:26</a> (? ver <span class=\"greek\">ἐλπίς</span> 1bα); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:18</a>; 8:20; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:10</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:2</a>. — Em <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:6</a>, <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐλπίδι</span> indica a base do processo judicial, assim como ἐ. <span class=\"greek\">εὐεργεσίᾳ</span> em <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:9</a>. <span class=\"greek\">ἀπολύειν</span> τ. <span class=\"greek\">γυναῖκα</span> ἐ. <span class=\"greek\">πορνείᾳ</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:9</a> (cf. Dio Chrys. 26 [43], 10, <span class=\"greek\">ἀπολύειν</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἀργυρίῳ</span>; Ath. 2, 3, <span class=\"greek\">κρίνεσθαι</span> … <span class=\"greek\">μὴ</span> ἐ. <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀνόματι</span>, ἐ. <span class=\"greek\">δὲ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀδικήματι</span>). <span class=\"greek\">γυναικὸς</span> ἐ. <span class=\"greek\">πόλλαις</span> <span class=\"greek\">ἁμαρτίαις</span> <span class=\"greek\">διαβληθείσης</span>, Papias (2:17). Com base no testemunho de duas testemunhas (cf. Appian, Iber. 79 §343, <span class=\"greek\">ἤλεγχον</span> ἐ. <span class=\"greek\">μάρτυσι</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:28</a> (Dt 17:6); uso semelhante de ἐ. <span class=\"greek\">τινί</span>, <i>com base em alguma coisa</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:6</a>; 9:10, 15 (aqui também pode receber sentido temporal; ver ⑱ adiante), 17. <span class=\"greek\">ἁμαρτάνειν</span> ἐ. <span class=\"greek\">τῷ</span> <span class=\"greek\">ὁμοιώματι</span> τ. <span class=\"greek\">παραβάσεως</span> <span class=\"greek\">Ἀδάμ</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:14</a> (<span class=\"greek\">ὁμοίωμα</span> 1). <span class=\"greek\">δαπανᾶν</span> ἐ. <span class=\"greek\">τινι</span>, <i>custear as despesas de alguém</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:24</a>. <span class=\"greek\">ἀρκεῖσθαι</span> ἐ. <span class=\"greek\">τινι</span>, <i>contentar-se com algo</i>, 3J 10.</p>\n<p class=\"entry-text\"><b>ⓑ Com verbos de crer, esperar e confiar:</b> <span class=\"greek\">πεποιθέναι</span> (Wsd 3:9; Sus 35; 1 Macc 10:71; 2 Macc 7:40 e frequentemente), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:22</a>; 18:9; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:9</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:13</a> (2 Km 22:3). <span class=\"greek\">πιστεύειν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:25</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:33</a>; 10:11; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:6</a> (as três últimas, Is 28:16). <span class=\"greek\">ἐλπίζειν</span> (2 Macc 2:18; Sir 34:7), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:12</a> (Is 11:10); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:10</a>; 6:17; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:3</a>. <span class=\"greek\">παρρησιάζεσθαι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:3</a>.</p>\n<p class=\"entry-text\"><b>ⓒ Após verbos que exprimem sentimentos, opiniões etc.: com respeito a, por causa de, em decorrência de, com</b> (Hom. e outros): <span class=\"greek\">διαταράσσεσθαι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:29</a>; <span class=\"greek\">ἐκθαυμάζειν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:17</a>; <span class=\"greek\">ἐκπλήσσεσθαι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:28</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:22</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:32</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:12</a>; <span class=\"greek\">ἐξίστασθαι</span> (Jdth 11:16; Wsd 5:2 e outros), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:47</a>; <span class=\"greek\">ἐπαισχύνεσθαι</span> (Is 1:29), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:21</a>; <span class=\"greek\">εὐφραίνεσθαι</span> (Sir 16:1; 18:32; 1 Macc 11:44), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:20</a>; <span class=\"greek\">θαμβεῖσθαι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:24</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:9</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:10</a>; <span class=\"greek\">θαυμάζειν</span> (Lev 26:32; Jdth 10:7 e outros; Jos., Ant. 10, 277), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:17</a>, variante; <span class=\"greek\">μακροθυμεῖν</span> (Sir 18:11; 29:8; 35:19), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:26</a>, 29; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:7</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:7</a>; <span class=\"greek\">μετανοεῖν</span> (Plut., Ag. 803 [19, 5]; Ps.-Lucian, Salt. 84; Prayer of Manasseh [=Odes 12] 7; Just., A I, 61, 10; D. 95, 3 e outros), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:21</a>; <span class=\"greek\">ὀδυνᾶσθαι</span> (cf. Tob 6:15), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:38</a>; <span class=\"greek\">ὀργίζεσθαι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:17</a>; <span class=\"greek\">σπλαγχνίζεσθαι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:14</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:13</a>; <span class=\"greek\">συλλυπεῖσθαι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:5</a>; <span class=\"greek\">στυγνάζειν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:22</a>; <span class=\"greek\">χαίρειν</span> (PEleph 13, 3; Jos., Ant. 1, 294; Tob 13:15; Bar 4:33; JosAs 4:2; Ar. 15, 7), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:13</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:14</a>; 13:17; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:19</a> e outros; <span class=\"greek\">χαρὰν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παράκλησιν</span> <span class=\"greek\">ἔχειν</span>, Phlm 7; <span class=\"greek\">χαρὰ</span> <span class=\"greek\">ἔσται</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:7</a>; cf. v. 10 (Jos., Ant. 6, 116, ἡ ἐ. <span class=\"greek\">τῇ</span> <span class=\"greek\">νίκῃ</span> <span class=\"greek\">χαρά</span>).</p>\n<p class=\"entry-text\">Também com verbos que denotam sentimentos suscitados: <span class=\"greek\">παραζηλοῦν</span> e <span class=\"greek\">παροργίζειν</span>, <i>provocar ciúme e ira em</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:19</a> (Dt 32:21); <span class=\"greek\">παρακαλεῖν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:7a</a> (cf. Just., D. 78:8, <span class=\"greek\">παράκλησιν</span> <span class=\"greek\">ἐχουσῶν</span> ἐ.); e verbos que indicam a expressão das emoções: <span class=\"greek\">ἀγαλλιᾶσθαι</span> (cf. Tob 13:15; Ps 69:5), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:47</a>; Hs 8, 1, 18; 9, 24, 2; <span class=\"greek\">καυχᾶσθαι</span> (Diod S 16, 70; Sir 30:2), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:2</a>; <span class=\"greek\">κοπετὸν</span> <span class=\"greek\">ποιεῖν</span> (cf. 3 Macc 4:3), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:2</a>; <span class=\"greek\">ὀλολύζειν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:1</a>; <span class=\"greek\">αἰνεῖν</span> (cf. X., An. 3, 1, 45 e outros), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:20</a>; <span class=\"greek\">δοξάζειν</span> (Polyb. 6, 53, 10; cf. Diod S 17, 21, 4, <span class=\"greek\">δόξα</span> ἐ. <span class=\"greek\">ἀνδρείᾳ</span>, «fama decorrente da bravura»), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:21</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:13</a>; <span class=\"greek\">εὐχαριστεῖν</span>, <i>dar graças por algo</i> (ver <span class=\"greek\">εὐχαριστέω</span> 2; UPZ 59, 10 [168 a.C.], ἐ. <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐρρῶσθαί</span> <span class=\"greek\">σε</span> τ. <span class=\"greek\">θεοῖς</span> <span class=\"greek\">εὐχαρίστουν</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:4</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:15</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:9</a>.</p>\n<p class=\"entry-text\"><b><span class=\"greek\">ἐφ</span>’ ᾧ = <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">ὅτι</span></b>, <i>por esta razão, porque</i> (Diod S 19, 98; Appian, Bell. Civ. 1, 112 §520; Ael. Aristid. 53 p. 640 D.; Synes., Ep. 73 p. 221c; Damasc., Vi. Isid. 154; Syntipas p. 12, 9; 127, 8; Thomas Mag., <span class=\"greek\">ἐφ</span>’ ᾧ <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">διότι</span>; cf. W-S. §24, 5b e 12s.; ver WKümmel, D. Bild des Menschen im NT 1948, 36–40), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:12</a> (SLyonnet, Biblica 36, 1955, 436–56, rejeita aqui o sentido causal. Sobre a probabilidade de expressão idiomática comercial, ver FDanker, FGingrich Festschr. 1972, 104s.; também <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:12</a>, Sin under Law: NTS 14, 1968, 424–39; contra ele, SPorter, TynBull 41, 1990, 3–30, também NTS 39, 1993, 321–33; diferentemente, JFitzmyer, Anchor Bible Comm.: Romans, ad loc., «com o resultado de que todos pecaram»); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:4</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:12</a>; <i>pois, de fato</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:10</a>.</p>\n<p class=\"entry-text\"><b>⑦ Marcador de acréscimo ao que já existe; a, além de, em acréscimo a.</b> Com dativo (Hom. e outros; PEleph 5, 17 [284/283 a.C.], <span class=\"greek\">μηνὸς</span> <span class=\"greek\">Τῦβι</span> <span class=\"greek\">τρίτῃ</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">εἰκάδι</span>; Tob 2:14; Sir 3:27; 5:5): <span class=\"greek\">προσέθηκεν</span> <span class=\"greek\">τοῦτο</span> ἐ. <span class=\"greek\">πᾶσιν</span>, <i>acrescentou isso a tudo o mais</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:20</a> (cf. Lucian, Luct. [On Funerals] 24). ἐ. τ. <span class=\"greek\">παρακλήσει</span> <span class=\"greek\">ἡμῶν</span>, <i>além de nosso consolo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:13</a>. <span class=\"greek\">λύπη</span> ἐ. <span class=\"greek\">λύπῃ</span>, <i>tristeza sobre tristeza</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:27</a>, variante (cf. Soph., Oed. C. 544; também Polyb. 1, 57, 1, <span class=\"greek\">πληγὴ</span> ἐ. <span class=\"greek\">πληγῇ</span>; Plut., Mor. 123f; Polyaenus 5, 52, ἐ. <span class=\"greek\">φόνῳ</span> <span class=\"greek\">φόνον</span>; Quint. Smyrn. 5, 602, ἐ. <span class=\"greek\">πένθει</span> <span class=\"greek\">πένθος</span>, «tristeza sobre tristeza»; Sir 26:15). ἐ. <span class=\"greek\">τῇ</span> <span class=\"greek\">σῇ</span> <span class=\"greek\">εὐχαριστίᾳ</span>, <i>à tua oração de ação de graças</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:16</a>. Talvez também <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:1</a>. ἐ. <span class=\"greek\">πᾶσι</span> <span class=\"greek\">τούτοις</span>, <i>a tudo isso</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:14</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:26</a>, variante (X., Mem. 1, 2, 25 e outros; Sir 37:15; cf. 1 Macc 10:42; Just., D. 133, 1, ἐ. <span class=\"greek\">τούτοις</span> <span class=\"greek\">πᾶσι</span>). — Com acusativo, acréscimo a algo da mesma espécie, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:27</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:25</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:18a</a>. <span class=\"greek\">λύπην</span> ἐ. <span class=\"greek\">λύπην</span>, <i>tristeza sobre tristeza</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:27</a> (cf. Is 28:10, 13; Ezk 7:26; Ps 68:28).</p>\n<p class=\"entry-text\"><b>⑧ Marcador de perspectiva; tendo em consideração, no que diz respeito a, com base em, concernente a, sobre</b>, com genitivo (Antig. Car. 164, ἐ. <span class=\"greek\">τῶν</span> <span class=\"greek\">οἴνων</span> <span class=\"greek\">ἀλλοιοῦσθαι</span>; 4 Macc 2:9, ἐ. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἑτέρων</span> … <span class=\"greek\">ἔστιν</span> <span class=\"greek\">ἐπιγνῶναι</span> <span class=\"greek\">τοῦτο</span>, <span class=\"greek\">ὅτι</span> …; Ath. 29, 2, <span class=\"greek\">τὰ</span> ἐ. <span class=\"greek\">τῆς</span> <span class=\"greek\">μανίας</span> <span class=\"greek\">πάθη</span>): ἐ. <span class=\"greek\">δύο</span> ἢ <span class=\"greek\">τριῶν</span> <span class=\"greek\">μαρτύρων</span>, <i>com base no depoimento de duas ou três testemunhas</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:19</a> (cf. TestAbr A 13 p. 92, 22ss. [Stone p. 32]). Semelhante na expressão ἐ. <span class=\"greek\">στόματος</span> <span class=\"greek\">δύο</span> <span class=\"greek\">μαρτύρων</span> (Dt 19:15), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:16</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:1</a>. <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτῆς</span>, <i>com base nela</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:11</a>. <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἀληθείας</span>, <i>fundamentado na verdade</i> = <i>segundo a verdade, verdadeiramente</i> (Demosth. 18, 17, <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἀληθείας</span> <span class=\"greek\">οὐδεμιᾶς</span> <span class=\"greek\">εἰρημένα</span>; POxy 255, 16 [48 d.C.]; Da 2:8; Tob 8:7; En 104:11), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:14</a>, 32; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:25</a>; 20:21; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:27</a>. <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἑαυτοῦ</span>, <i>baseado em si mesmo</i> = <i>para si mesmo, por si mesmo</i> (X., An. 2, 4, 10; Demosth. 18, 224, <span class=\"greek\">ἐκρίνετο</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἑαυτοῦ</span>; Dionys. Hal., Comp. Verb. 16, ἐ. <span class=\"greek\">σεαυτοῦ</span>; cf. Kühner-G. I 498e), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:7</a>.</p>\n<p class=\"entry-text\">Para introduzir o objeto sobre o qual se deve falar ou agir: <span class=\"greek\">λέγειν</span> ἐ. <span class=\"greek\">τινος</span>, <i>falar de, acerca de algo</i> (Pla., Charm. 155d, Leg. 2, 662d; Isocr. 6, 41; Aelian, VH 1, 30; Jer 35:8; EpArist 162; 170; Ath. 5:1, ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">νοητοῦ</span> … <span class=\"greek\">δογματίζειν</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:16</a>. <i>Fazer algo em, no caso de</i> (cf. 1 Esdr 1:22): <span class=\"greek\">σημεῖα</span> <span class=\"greek\">ποιεῖν</span> ἐ. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀσθενούντων</span>, <i>realizar milagres nos enfermos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:2</a>. — Quanto a B 13:6, ver <span class=\"greek\">τίθημι</span> 1bζ. — <i>Quanto a algo</i> (Aristot., Pol. 1280a, 17; 4 Macc 12:5, <span class=\"greek\">τῶν</span> ἐ. <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span> … <span class=\"greek\">πραγμάτων</span>; Just., A I, 5, 1, <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἡμῶν</span>, «no nosso caso», D. 131, 4; Ath. 15, 3, ἐ. <span class=\"greek\">τῆς</span> <span class=\"greek\">ὕλης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, «no tocante a Deus e à matéria»): ἐ. <span class=\"greek\">τινων</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">ἐγκρατεύεσθαι</span>, <i>em certas questões é necessário exercer autocontrole</i>, Hm 8:1. <span class=\"greek\">οὔτε</span> … <span class=\"greek\">οἴδασι</span> <span class=\"greek\">τὸν</span> ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πυροῦ</span> <span class=\"greek\">σπόρον</span>, <i>nem compreendem o sentido (figurado) da semeadura do trigo</i>, AcPlCor 2:26 (cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.36\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:36s</a>.).</p>\n<p class=\"entry-text\"><b>⑨ Marcador de poder, autoridade ou controle sobre alguém ou alguma coisa; sobre.</b> <b>ⓐ Com genitivo</b> (Hdt. 5, 109 e outros; Mitt-Wilck. I/1, 124, 1 = BGU 1120, 1 [5 a.C.], <span class=\"greek\">πρωτάρχῳ</span> ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κριτηρίου</span>; 287, 1; LXX; AscIs 2:5, <span class=\"greek\">τοῦ</span> ἐ. <span class=\"greek\">τῶν</span> <span class=\"greek\">πραγματε</span>[ι] <span class=\"greek\">ῶν</span> = Denis p. 109): <span class=\"greek\">βασιλεύειν</span> ἐ. <span class=\"greek\">τινος</span>, <i>reinar sobre alguém</i> (Judg 9:8, 10; 1 Km 8:7), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:10</a>. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">βασιλείαν</span> ἐ. <span class=\"greek\">τῶν</span> <span class=\"greek\">βασιλέων</span>, <i>ter domínio sobre os reis</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:18</a>. <span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">ἔχειν</span> ἐ. <span class=\"greek\">τινος</span>, <i>ter poder sobre alguém</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 20:6</a>. <span class=\"greek\">διδόναι</span> <span class=\"greek\">ἐξουσίαν</span> ἐ. <span class=\"greek\">τινος</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:26</a>. <span class=\"greek\">καθιστάναι</span> <span class=\"greek\">τινὰ</span> ἐ. <span class=\"greek\">τινος</span>, <i>constituir alguém sobre alguma coisa ou pessoa, encarregar alguém</i> (Pla., Rep. 5, 460b; Demosth. 18, 118; Gen 39:4s.; 1 Macc 6:14; 10:37; 2 Macc 12:20 e outros; EpArist 281; <span class=\"greek\">τεταγμένος</span>, En 20:5), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:45</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:42</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:3</a>. <span class=\"greek\">εἶναι</span> ἐ. <span class=\"greek\">τινος</span> (Synes., Ep. 79 p. 224d; Tob 1:22; Jdth 14:13; 1 Macc 10:69): <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἦν</span> ἐ. <span class=\"greek\">πάσης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γάζης</span> <span class=\"greek\">αὐτῆς</span>, <i>aquele que estava encarregado de todo o tesouro dela</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:27</a>. De Deus: ὁ <span class=\"greek\">ὢν</span> ἐ. <span class=\"greek\">πάντων</span> (Apollonius of Tyana [século I d.C.] em Eus., PE 4, 13), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:5</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:6</a>. ὁ ἐ. <span class=\"greek\">τινος</span>, com <span class=\"greek\">ὤν</span> subentendido (Demosth. 18, 247 e outros; Diod S 13, 47, 6; Plut., Pyrrh. 385 [5, 7], Aemil. Paul. 267 [23, 6]; PTebt 5, 88 [118 a.C.], ὁ ἐ. τ. <span class=\"greek\">προσόδων</span>; 1 Macc 6:28; 2 Macc 3:7; 3 Macc 6:30 e outros; EpArist 110; 174): ὁ ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κοιτῶνος</span>, <i>o camareiro</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:20</a>.</p>\n<p class=\"entry-text\"><b>ⓑ Com dativo</b> (X., Cyr. 1, 2, 5; 2, 4, 25 e outros, An. 4, 1, 13; Demosth. 19, 113; Aeschines 2, 73; Esth 8:12e; Just., A II, 5, 2, <span class=\"greek\">ἀγγέλοις</span> <span class=\"greek\">οὓς</span> ἐ. <span class=\"greek\">τούτοις</span> <span class=\"greek\">ἔταξε</span>; cf. Ath. 24, 3; Ath. 6, 4, <span class=\"greek\">τὸν</span> ἐ. <span class=\"greek\">τῇ</span> <span class=\"greek\">κινήσει</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span> <span class=\"greek\">λόγον</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:47</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:44</a>.</p>\n<p class=\"entry-text\"><b>ⓒ Com acusativo</b> (X., Hell. 3, 4, 20 e outros; Dionys. Byz. §56, <span class=\"greek\">θεῷ</span> ἐ. <span class=\"greek\">πάντα</span> <span class=\"greek\">δύναμις</span>; LXX; PsSol 17:3, 32): <span class=\"greek\">βασιλεύειν</span> ἐ. <span class=\"greek\">τινα</span>, <i>reinar sobre alguém</i> (Gen 37:8; Judg 9:15 B e outros), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:33</a>; 19:14, 27; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:14</a>. <span class=\"greek\">καθιστάναι</span> <span class=\"greek\">τινὰ</span> ἐ. <span class=\"greek\">τινα</span>, <i>colocar alguém sobre outra pessoa</i> (X., Cyr. 4, 5, 58): <span class=\"greek\">κριτὴν</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὑμᾶς</span>, <i>como juiz sobre vós</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:14</a>; <span class=\"greek\">ἡγούμενον</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">Αἴγυπτον</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:10</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:7</a>, variante (Ps 8:7); 3:6; 10:21. <span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">ἔχειν</span> ἐ. <span class=\"greek\">τι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:9</a>; <span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">διδόναι</span> ἐ. <span class=\"greek\">τι</span> (Sir 33:20), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:1</a>; 10:19; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:8</a>; cf. 22:14. <span class=\"greek\">φυλάσσειν</span> <span class=\"greek\">φυλακὰς</span> ἐ. <span class=\"greek\">τι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:8</a> (cf. En 100:5). <span class=\"greek\">ὑπεραίρεσθαι</span> ἐ. <span class=\"greek\">τινα</span>, <i>exaltar-se acima de alguém</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:4</a> (cf. Da 11:36); mas também é possível aqui o sentido <i>contra</i> (ver ⑫ⓑ adiante). <span class=\"greek\">πιστὸς</span> ἐ. <span class=\"greek\">τι</span>, <i>fiel sobre algo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:21</a>, 23.</p>\n<p class=\"entry-text\"><b>⑩ Marcador de procedimento judicial; perante</b>, com acusativo, na linguagem dos tribunais: ἐ. <span class=\"greek\">ἡγεμόνας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">βασιλεῖς</span> <span class=\"greek\">ἄγεσθαι</span>, <i>ser conduzido perante governadores e reis</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:18</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:12</a> (cf. BGU 22, 36 [114 d.C.], <span class=\"greek\">ἀξιῶ</span> <span class=\"greek\">ἀκθῆναι</span> [=<span class=\"greek\">ἀχθῆναι</span>] τ. <span class=\"greek\">ἐνκαλουμένους</span> ἐ. <span class=\"greek\">σὲ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">δέουσαν</span> <span class=\"greek\">ἐπέξοδον</span>; Just., A II, 2, 12, ἐ. <span class=\"greek\">Οὔρβικον</span>). <span class=\"greek\">ὑπάγεις</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἄρχοντα</span>, <i>vais comparecer diante do magistrado</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.58\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:58</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:19</a>. <span class=\"greek\">ἤγαγον</span> <span class=\"greek\">αὐτὸν</span> ἐ. <span class=\"greek\">τὸν</span> <span class=\"greek\">Πιλᾶτον</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:1</a>. ἐ. <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀρχιερεῖς</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:21</a>. ἐ. <span class=\"greek\">Καίσαρα</span> <span class=\"greek\">πορεύεσθαι</span>, <i>apresentar-se perante o imperador</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:12</a>. ἐ. <span class=\"greek\">τὰς</span> <span class=\"greek\">συναγωγάς</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:11</a>; ἐ. <span class=\"greek\">τὸ</span> <span class=\"greek\">βῆμα</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:12</a>. Cf. ③ acima. Aqui o foco recai na transferência ao poder judiciário.</p>\n<p class=\"entry-text\"><b>⑪ Marcador de finalidade, objetivo ou resultado; a, para</b>, com acusativo (Demetr.: 722 Fgm. 2, 3 Jac., ἐ. <span class=\"greek\">κατοικίαν</span>): ἐ. <span class=\"greek\">τὸ</span> <span class=\"greek\">βάπτισμα</span>, <i>para o batismo</i> = <i>para serem batizados</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:7</a> (cf. Just., A I, 61, 10, ἐ. <span class=\"greek\">τὸ</span> <span class=\"greek\">λουτρόν</span>; D. 56, 1, ἐ. <span class=\"greek\">τὴν</span> … <span class=\"greek\">κρίσιν</span> <span class=\"greek\">πεμφθεῖσι</span>). ἐ. <span class=\"greek\">τὴν</span> <span class=\"greek\">θεωρίαν</span> <span class=\"greek\">ταύτην</span>, <i>para (ver) esse espetáculo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:48</a> (similarmente Hom. e outros; POxy 294, 18 [22 d.C.]; LXX; Tat. 23, 2, ἐ. <span class=\"greek\">τὴν</span> <span class=\"greek\">θέαν</span>). ἐ. <span class=\"greek\">τὸ</span> <span class=\"greek\">συμφέρον</span>, <i>para (nosso) proveito</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:10</a> (cf. Tat. 6, 1; 34, 2, <span class=\"greek\">οὐκ</span> ἐ. <span class=\"greek\">τι</span> <span class=\"greek\">χρήσιμον</span>, «sem utilidade»). ἐ. <span class=\"greek\">σφαγήν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:32</a> (Is 53:7); cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:5</a>; ἐ. τ. <span class=\"greek\">τελειότητα</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:1</a>. ἐ. <span class=\"greek\">τοῦτο</span>, <i>para isso</i> (X., An. 2, 5, 22; Jos., Ant. 12, 23), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:43</a>. <span class=\"greek\">ἐφ</span>’ ὅ, <i>para quê? por qual razão?</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:50</a>, variante (ver <span class=\"greek\">ὅς</span> 1bα e 1iβ). Cf. ⑯.</p>\n<p class=\"entry-text\"><b>⑫ Marcador de oposição hostil; contra.</b> <b>ⓐ Com dativo</b> (Hom. e outros; 2 Macc 13:19; Sir 28:23, variante; figuradamente, Ath. 22, 7, <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">λόγους</span>, «contraprovas»), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:52s</a>. (ver o emprego do acusativo em b abaixo); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:19</a>. Cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:7</a>, variante (1bβ acima).</p>\n<p class=\"entry-text\"><b>ⓑ Com acusativo</b> (Hdt. 1, 71; X., Hell. 3, 4, 20 e outros; Jos., Ant. 13, 331; LXX; En; TestJud 3:1 e outros; JosAs 19:2; Just., D. 103, 7; Tat. 36, 2): <span class=\"greek\">ὥρμησαν</span> ἐ. <span class=\"greek\">αὐτόν</span>, <i>precipitaram-se contra ele</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.57\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:57</a>. <span class=\"greek\">ἔρχεσθαι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:31</a>. <span class=\"greek\">ἐπαναστήσονται</span> <span class=\"greek\">τέκνα</span> ἐ. <span class=\"greek\">γονεῖς</span>, <i>filhos se levantarão contra pais</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:21</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:12</a>; cf. <span class=\"greek\">ἔθνος</span> ἐ. <span class=\"greek\">ἔθνος</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:7</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:8</a>. <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἑαυτόν</span>, <i>dividido contra si mesmo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:26</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:24s</a>., 26; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:17s</a>.; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:18</a> (ver Ps 40:10); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:27</a>; 13:50 e outros. — <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:53</a> (quatro vezes; a primeira e a terceira ocorrências com acusativo são provavelmente influenciadas pelo uso em Mi 7:6; o dativo de <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:52s</a>. [ver a acima], com verbo que expressa uma circunstância, está de acordo com o grego mais antigo [Il. e outros], que prefere o acusativo com verbos de movimento referentes à hostilidade). Cf. ⑮.</p>\n<p class=\"entry-text\"><b>⑬ Marcador de número ou medida, com acusativo</b> (Hdt. e outros; LXX; GrBar 3:6): ἐ. <span class=\"greek\">τρίς</span> (CIG 1122, 9; PHolm α18), <i>três vezes</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:16</a>; 11:10. Também ἐ. <span class=\"greek\">πολύ</span>, <i>mais de uma vez</i>, Hm 4, 1, 8. ἐ. <span class=\"greek\">πολύ</span> (também grafado <span class=\"greek\">ἐπιπολύ</span>), em sentido diferente, <i>em grande medida, cuidadosamente</i> (Hdt., Thu. e outros; Lucian, D. Deor. 6, 2; 25, 2; 3 Macc 5:17; Jos., Ant. 17, 107), B 4:1. ἐ. <span class=\"greek\">πλεῖον</span>, <i>em maior medida, mais adiante</i> (Hdt., Thu. e outros; Diod S 11, 60, 5 e outros; provavelmente 2 Macc 12:36; TestGad 7:2; Ar. 4, 3; Ath. 7, 1, ἐ. <span class=\"greek\">το</span> <span class=\"greek\">πλεῖστον</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:9</a>; 1 Cl 18:3 (Ps 50:4). ἐ. <span class=\"greek\">τὸ</span> <span class=\"greek\">χεῖρον</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:13</a>. <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὅσον</span>, <i>na medida em que, enquanto</i> (Diod S 1, 93, 2; Maximus Tyr. 11, 3c, <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὅσον</span> <span class=\"greek\">δύναται</span>; Hierocles 14 p. 451), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:40</a>, 45; B 4:11; 17:1; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:13</a>.</p>\n<p class=\"entry-text\"><b>⑭ Marcador que indica a pessoa a quem, em favor de quem ou a respeito de quem algo é feito; a, sobre, acerca de.</b> <b>ⓐ Com dativo.</b> <span class=\"greek\">πράσσειν</span> <span class=\"greek\">τι</span> ἐ. <span class=\"greek\">τινι</span>, <i>fazer algo a alguém</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:35</a> (assim Appian, Bell. Civ. 3, 15 §51; cf. <span class=\"greek\">δρᾶν</span> <span class=\"greek\">τι</span> ἐ. <span class=\"greek\">τινι</span>, Hdt. 3, 14; Aelian, NA 11, 11); <i>a respeito de</i>: <span class=\"greek\">γεγραμμένα</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτῷ</span>, <i>coisas escritas a respeito dele</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:16</a> (cf. Hdt. 1, 66). <span class=\"greek\">προφητεύειν</span> ἐ. <span class=\"greek\">τινι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:11</a>. <span class=\"greek\">μαρτυρεῖν</span>, <i>dar testemunho a respeito de</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:4</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:16</a>. ἐ. <span class=\"greek\">σοὶ</span> … <span class=\"greek\">φανερώσει</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">λύτρον</span>, <i>o Senhor manifestará a salvação a ti</i>, GJs 7:2.</p>\n<p class=\"entry-text\"><b>ⓑ Com acusativo.</b> <b>α.</b> ὁ <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">γεγόνει</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σημεῖον</span>, <i>o homem em quem se realizara o milagre</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:22</a> (cf. Just., D. 128, 1, <span class=\"greek\">κρίσεως</span> <span class=\"greek\">γεγενημένης</span> ἐ. <span class=\"greek\">Σόδομα</span>). <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">λέγεται</span> <span class=\"greek\">ταῦτα</span>, <i>aquele acerca de quem isso foi dito</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:13</a> (cf. ἐ. <span class=\"greek\">πόρρω</span> <span class=\"greek\">οὖσαν</span> [<span class=\"greek\">γενεὰν</span>] <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">λαλῶ</span>, En 1:2). <span class=\"greek\">γέγραπται</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτόν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:12s</a>.; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:9</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:18</a>; <span class=\"greek\">βάλλειν</span> <span class=\"greek\">κλῆρον</span> ἐ. <span class=\"greek\">τι</span>, <i>lançar sortes por alguma coisa</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:24</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:24</a> (Ps 21:19). <span class=\"greek\">ἀνέβη</span> ὁ <span class=\"greek\">κλῆρος</span> ἐ. <span class=\"greek\">Συμεών</span>, <i>a sorte recaiu em favor de Simeão</i>, GJs 24:4.</p>\n<p class=\"entry-text\"><b>β. De poderes, condições etc., que sobrevêm a alguém ou sob cuja influência alguém se encontra: sobre, em, a, para.</b> <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">ῥῆμα</span> <span class=\"greek\">θεοῦ</span> ἐ. <span class=\"greek\">Ἰωάννην</span>, <i>a palavra de Deus veio a João</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:2</a> (cf. Jer 1:1). Das bênçãos divinas (cf. En 1:8; ParJer 5:28), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:13</a>; 12:28; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:6</a>; 11:20; cf. 10:9; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:10</a>. <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἐπισκηνώσῃ</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐμὲ</span> ἡ <span class=\"greek\">δύναμις</span> τ. <span class=\"greek\">Χριστοῦ</span>, <i>para que o poder de Cristo repouse sobre mim</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:9</a>. <span class=\"greek\">χάρις</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτό</span>, <i>a graça de Deus estava sobre ele</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:40</a>.</p>\n<p class=\"entry-text\">Diferentes verbos são usados em referência ao Espírito Santo, em função ativa ou passiva, em conexão com ἐ. <span class=\"greek\">τινα</span>: <span class=\"greek\">ἐκχεῖν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:17s</a>. (Jo 3:1s.); cf. 10:45; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:6</a>. <span class=\"greek\">ἀποστέλλειν</span> (<span class=\"greek\">ἐξαποστέλλειν</span>, variante), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:49</a>. <span class=\"greek\">ἐπέρχεσθαι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:35</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:8</a> (Just., D. 87, 3; cf. <span class=\"greek\">ἔρχεσθαι</span>, A I, 33, 6; D. 49, 7, <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἠλίου</span> ἐ. <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰωάννην</span> <span class=\"greek\">ἐλθεῖν</span>). <span class=\"greek\">ἐπιπίπτειν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.44\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:44</a>. <span class=\"greek\">καταβαίνειν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:22</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:33</a>. <span class=\"greek\">τίθεσθαι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:18</a> (cf. Is 42:1). Também <span class=\"greek\">εἶναι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:25</a>; <span class=\"greek\">μένειν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:32s</a>.; <span class=\"greek\">ἀναπαύεσθαι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:14</a>. De experiências desagradáveis ou surpreendentes, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:12</a>, 65; 4:36; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:11</a>; 19:17; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:11</a>. — <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:43</a>; 21:35; cf. v. 34; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:4</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:6</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:3</a>. — <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:2</a>, 9; 15:3 (Ps 68:10). Do sangue dos justos, que recai sobre os assassinos, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:35</a>; 27:25; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:28</a>. Do cuidado que alguém lança sobre outro, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:7</a> (Ps 54:23).</p>\n<p class=\"entry-text\"><b>⑮ Marcador de sentimentos dirigidos a alguém; em, sobre, para, em direção a</b>, com acusativo, após palavras que exprimem fé, confiança ou esperança: <span class=\"greek\">πιστεύειν</span> ἐ. <span class=\"greek\">τινα</span>, com acusativo (Wsd 12:2; Just., D. 16:4 e outros), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:42</a>; 11:17; 16:31; 22:19; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:24</a>. <span class=\"greek\">πίστις</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:1</a>. <span class=\"greek\">πεποιθέναι</span> (Is 58:14), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:43</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:4</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:3</a>. <span class=\"greek\">ἐλπίζειν</span> (1 Ch 5:20; 2 Ch 13:18 e outros; PsSol 9:10; 17:3; Just., D. 16:4 e outros), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:13</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:5</a>. Após palavras que caracterizam emoção ou sua expressão: <i>por</i>, <span class=\"greek\">κόπτεσθαι</span> (Zech 12:10), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:7</a>; 18:9; <span class=\"greek\">κλαίειν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:28</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:9</a> (cf. JosAs 15:9, <span class=\"greek\">χαρήσεται</span> ἐ. <span class=\"greek\">σέ</span>); <span class=\"greek\">σπλαγχνίζεσθαι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:32</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:2</a>; 9:22; Hm 4, 3, 5; Hs 9, 24, 2; <span class=\"greek\">χρηστός</span>, <i>para com</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:35</a>; <span class=\"greek\">χρηστότης</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:22</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:7</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:23</a>. Sobretudo quando sentimentos e suas expressões são hostis: <i>contra, em direção a</i> (cf. <span class=\"greek\">λοιδορεῖν</span>, Just., D. 137, 2), <span class=\"greek\">ἀποτομία</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:22</a>; <span class=\"greek\">μαρτύριον</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:5</a>; <span class=\"greek\">μάρτυς</span> ἐ. τ. <span class=\"greek\">ἐμὴν</span> <span class=\"greek\">ψυχήν</span>, <i>testemunha contra a minha alma</i> (cf. Dssm., LO 258; 355 [LAE 304; 417]), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:23</a>; <span class=\"greek\">ἀσχημονεῖν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.36\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:36</a>; <span class=\"greek\">μοιχᾶσθαι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:11</a>; <span class=\"greek\">τολμᾶν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:2</a> (En 7:4); <span class=\"greek\">βρύχειν</span> τ. <span class=\"greek\">ὀδόντας</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.54\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:54</a>. Cf. ⑫.</p>\n<p class=\"entry-text\"><b>⑯ Marcador de objeto ou finalidade, com dativo; com referência a alguma coisa</b> (Hom., Thu. e outros; SIG 888, 5, ἐ. <span class=\"greek\">τῇ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρ</span>. <span class=\"greek\">σωτηρίᾳ</span>; PTebt 44, 6 [114 a.C.], <span class=\"greek\">ὄντος</span> <span class=\"greek\">μου</span> ἐ. <span class=\"greek\">θεραπείᾳ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἰσιείω</span>; LXX; TestJob 3:5, ὁ ἐ. <span class=\"greek\">τῇ</span> <span class=\"greek\">σωτηρίᾳ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐμῆς</span> <span class=\"greek\">ψυχῆς</span> <span class=\"greek\">ἐλθών</span>; Jos., Ant. 5, 101; Just., A I, 29, 1, ἐ. <span class=\"greek\">παίδων</span> <span class=\"greek\">ἀναστροφῇ</span>; D. 91, 4, ἐ. <span class=\"greek\">σωτηρίᾳ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πιστευόντων</span>): <span class=\"greek\">καλείν</span> <span class=\"greek\">τινα</span> ἐ. <span class=\"greek\">τινι</span>, <i>chamar alguém para alguma coisa</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:13</a> (sobre <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐλευθερίᾳ</span>, cf. Demosth. 23, 124; [59], 32); ἐ. <span class=\"greek\">ἀκαθαρσίᾳ</span>, <i>para impureza</i>, isto é, para que fôssemos impuros, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:7</a>; <span class=\"greek\">κτισθέντες</span> ἐ. <span class=\"greek\">ἔργοις</span> <span class=\"greek\">ἀγαθοῖς</span>, <i>criados para boas obras</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:10</a>. <span class=\"greek\">λογομαχεῖν</span> ἐ. <span class=\"greek\">καταστροφῇ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀκουόντων</span>, <i>discutir palavras para a ruína dos ouvintes</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:14</a> (cf. Eur., Hipp. 511; X., Mem. 2, 3, 19, ἐ. <span class=\"greek\">βλάβη</span>; Hdt. 1, 68, ἐ. <span class=\"greek\">κακῷ</span> <span class=\"greek\">ἀνθρώπου</span>; Polyb. 27, 7, 13 e PGM 4, 2440, <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἀγαθῷ</span> = «para o bem»). Cf. ⑪.</p>\n<p class=\"entry-text\"><b>⑰ Marcador na expressão idiomática de autorização, com dativo:</b> a fórmula ἐ. <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀνοματί</span> <span class=\"greek\">τινος</span>, <i>em nome de alguém</i>, usada com muitos verbos (Just., D. 39, 6 com <span class=\"greek\">γίνεσθαι</span>; de outro modo ἐ. <span class=\"greek\">ὀνόματος</span>, por exemplo A I, 61, 13; com <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> ὀ. e, nos juramentos, <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοῦ</span> ὀ., A II, 6, 6; D. 30, 3; 85, 2. — Ath. 23, 1, ἐ. <span class=\"greek\">ὀνόματι</span> <span class=\"greek\">εἰδώλων</span>. — <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀνόματι</span>, LXX; JosAs 9:1). A expressão ressalta a função autorizadora daquele cujo nome aparece no genitivo (cf. WHeitmüller, Im Namen Jesu 1903, 13ss.; «em ligação com o nome, ou mediante seu uso, isto é, nomeando, proclamando ou invocando o nome» [p. 88]): <span class=\"greek\">βαπτίζειν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:38</a>; <span class=\"greek\">δέχεσθαί</span> <span class=\"greek\">τινα</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:5</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:37</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:48</a>; <span class=\"greek\">διδάσκειν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:18</a>; 5:28; <span class=\"greek\">δύναμιν</span> <span class=\"greek\">ποιεῖν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:39</a>; <span class=\"greek\">ἐκβάλλειν</span> <span class=\"greek\">δαιμόνια</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:49</a>, variante; <span class=\"greek\">ἔρχεσθαι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:5</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:6</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:8</a>; <span class=\"greek\">κηρύσσειν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:47</a>; <span class=\"greek\">λαλεῖν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:17</a>; 5:40. Semanticamente distinta da anterior, mas formalmente análoga, é <span class=\"greek\">καλεῖν</span> <span class=\"greek\">τινα</span> ἐ. <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">τινος</span>, <i>dar a alguém o nome de outrem</i> (2 Esdr 17:63), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.59\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:59</a>. — <span class=\"greek\">ὄνομα</span> 1dγג. — M-M.</p>\n<p class=\"entry-text\"><b>⑱ Marcador de associações temporais; no tempo de, em, durante, por.</b> <b>ⓐ Com genitivo</b>, o intervalo em que ocorre um acontecimento ou estado (Hom.+); <i>no tempo de, sob</i> (reis ou outros governantes): <i>no tempo de Eliseu</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:27</a> (cf. Just., D. 46, 6, ἐ. <span class=\"greek\">Ἠλίου</span>). ἐ. <span class=\"greek\">τῆς</span> <span class=\"greek\">μετοικεσίας</span>, <i>no tempo do exílio</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:11</a>. <i>Sob</i> = durante o governo ou a administração de (Hes., Op. 111; Hdt. 6, 98 e outros; OGI 90, 15; PAmh 43, 2 [173 a.C.]; UPZ 162 V, 5 [117 a.C.]; 1 Esdr 2:12; 1 Macc 13:42; 2 Macc 15:22; Jos., Ant. 12, 156, ἐ. <span class=\"greek\">ἀρχιερέως</span> Ὀ.): ἐ. <span class=\"greek\">Ἀβιαθὰρ</span> <span class=\"greek\">ἀρχιερέως</span>, <i>sob, no tempo de Abiatar, o sumo sacerdote</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:26</a>; ἐ. <span class=\"greek\">ἀρχιερέως</span> <span class=\"greek\">Ἅννα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Καιάφα</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:2</a>; ἐ. <span class=\"greek\">Κλαυδίου</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:28</a> (Just., A I, 26, 2); ἐ. <span class=\"greek\">τῶν</span> <span class=\"greek\">πατέρων</span>, <i>no tempo dos pais</i>, 1 Cl 23:3. <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐσχάτων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἡμερῶν</span>, <i>nos últimos dias</i> (Gen 49:1; Num 24:14; Mi 4:1; Jer 37:24; Da 10:14), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:3</a>; Hs 9, 12, 3; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:2</a>. <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐσχάτου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">χρόνου</span>, <i>no último tempo</i>, Jd 18. <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐσχάτου</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">χρόνων</span>, <i>no fim dos tempos/eras</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:20</a>. ἐ. <span class=\"greek\">τῶν</span> <span class=\"greek\">προσευχῶν</span> <span class=\"greek\">μου</span>, <i>quando oro, em minhas orações</i> (cf. PTebt 58, 31 [111 a.C.], ἐ. τ. <span class=\"greek\">διαλόγου</span>, «durante a discussão»; 4 Macc 15:19, ἐ. τ. <span class=\"greek\">βασάνων</span>, «durante as torturas»; Sir 37:29; 3 Macc 5:40; Demetr.: 722 Fgm. 1, 14 Jac., ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀρίστου</span>; Synes., Ep. 121 p. 258c, ἐ. <span class=\"greek\">τῶν</span> <span class=\"greek\">κοινῶν</span> <span class=\"greek\">ἱερῶν</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:10</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:16</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:2</a>; Phlm 4.</p>\n<p class=\"entry-text\"><b>ⓑ Com dativo</b>, tempo em que ou durante o qual (Hom. e outros; PTebt 5, 66 [118 a.C.]; PAmh 157; LXX; Just., A I, 13, 3, ἐ. <span class=\"greek\">χρόνοις</span> <span class=\"greek\">Τίερίου</span>): <i>em, no, na época de, durante</i>. ἐ. <span class=\"greek\">τοῖς</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">χρόνοις</span>, <i>nestes tempos presentes</i>, 2 Cl 19:4. ἐ. <span class=\"greek\">τῇ</span> <span class=\"greek\">πρώτῃ</span> <span class=\"greek\">διαθήκῃ</span>, <i>no tempo da primeira aliança</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:15</a>. ἐ. <span class=\"greek\">συντελείᾳ</span> τ. <span class=\"greek\">αἰώνων</span>, <i>na consumação dos séculos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:26</a> (Tat. 13, 1, ἐ. ς. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span>; cf. Sir 22:10 e PLond III, 954, 18 p. 154 [260 d.C.], ἐ. <span class=\"greek\">τέλει</span> τ. <span class=\"greek\">χρόνου</span>; POxy 275, 20 [66 d.C.], ἐ. <span class=\"greek\">συνκλεισμῷ</span> τ. <span class=\"greek\">χρόνου</span>; En 27:3, <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐσχάτοις</span> <span class=\"greek\">αἰώσιν</span>). ἐ. <span class=\"greek\">τῇ</span> <span class=\"greek\">θυσίᾳ</span>, <i>no momento do sacrifício, juntamente com ele</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:17</a>. ἐ. <span class=\"greek\">πάσῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">μνείᾳ</span> <span class=\"greek\">ὑμῶν</span>, <i>a cada lembrança de vós</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:3</a>. ἐ. <span class=\"greek\">παροργισμῷ</span> <span class=\"greek\">ὑμῶν</span>, <i>durante vossa ira</i>, isto é, enquanto estais irados, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.26\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:26</a>. ἐ. <span class=\"greek\">πάσῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀνάγκῃ</span>, <i>em toda a (nossa) aflição</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:7b</a>. ἐ. <span class=\"greek\">πάσῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">θλίψει</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:4</a>. ἐ. <span class=\"greek\">τούτῳ</span>, <i>nesse ínterim</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:27</a> (Lucian, Dial. Deor. 17, 2; cf. Philops. 14 p. 41; Syntipas p. 76, 2, <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἡμέραις</span> <span class=\"greek\">ἑπτα</span>; 74, 6).</p>\n<p class=\"entry-text\"><b>ⓒ Com acusativo.</b> <b>α. Respondendo à pergunta «quando?»; em</b>: ἐ. <span class=\"greek\">τὴν</span> <span class=\"greek\">αὔριον</span> (Sb 6011, 14 [século I a.C.]; PRyl 441, ἐ. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐπαύριον</span>), <i>no dia seguinte</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:35</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:5</a>. ἐ. <span class=\"greek\">τὴν</span> <span class=\"greek\">ὥραν</span> τ. <span class=\"greek\">προσευχῆς</span>, <i>à hora da oração</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:1</a> (Polyaenus 8, 17, ἐ. <span class=\"greek\">ὥραν</span> <span class=\"greek\">ὡρισμένην</span>).</p>\n<p class=\"entry-text\"><b>β. Respondendo à pergunta «por quanto tempo?»; por, durante certo período</b> (Hom. e outros; Mitt-Wilck. II/2, 170, 8 = BGU 1058, 9 [13 a.C.]; POxy 275, 9; 15, ἐ. <span class=\"greek\">τὸν</span> <span class=\"greek\">ὅλον</span> <span class=\"greek\">χρόνον</span>; PTebt 381, 19, <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">χρόνον</span> <span class=\"greek\">περίεστιν</span> ἡ <span class=\"greek\">μήτηρ</span>; LXX; En 106:15; TestJob 30:2, ἐ. <span class=\"greek\">ὥρας</span> <span class=\"greek\">τρεῖς</span>; TestJud 3:4; TestGad 5:11; Jos., Ant. 11, 2; Just., D. 142, 1, ἐ. <span class=\"greek\">ποσόν</span>, «por algum tempo»): ἐ. <span class=\"greek\">ἔτη</span> <span class=\"greek\">τρία</span>, <i>durante três anos</i> (Phlegon: 257 Fgm. 36, 2, 1 Jac.), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:25</a>. ἐ. <span class=\"greek\">τρεῖς</span> <span class=\"greek\">ἡμέρας</span>, <i>durante três dias</i> (Diod S 13, 19, 2; Arrian, Anab. 4, 9, 4; GDI 4706, 119 [Thera], <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἀμέρας</span> <span class=\"greek\">τρεῖς</span>), GPt 8:30 e outros. ἐ. <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">πλείους</span>, <i>ao longo de muitos dias</i> (Jos., Ant. 4, 277), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:31</a>; também 16:18 (ἐ. <span class=\"greek\">πολλὰς</span> <span class=\"greek\">ἡμέρας</span>, como Appian, Liby. 29 §124; cf. Diod S 3, 16, 4); 17:2; 19:8, 10, 34; 27:20; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.30\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:30</a>. ἐ. <span class=\"greek\">χρόνον</span>, <i>por algum tempo</i> (cf. Il. 2, 299; Hdt. 9, 22, 1; Apollon. Rhod. 4, 1257; Jos., Vi. 2), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:4</a>. ἐ. <span class=\"greek\">πλείονα</span> <span class=\"greek\">χρόνον</span> (Diod S 3, 16, 6; Hero Alex. I p. 344, 17), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:20</a>. <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὅσον</span> <span class=\"greek\">χρόνον</span>, <i>enquanto durar, pelo tempo em que</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:1</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.39\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:39</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:1</a>. Também <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὅσον</span>, <i>enquanto</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:15</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:13</a> (quanto a outros sentidos de <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὅσον</span>, ver ⑬ acima). <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἱκανόν</span> (subentende-se <span class=\"greek\">χρόνον</span>), <i>por bastante tempo</i> (EpArist 109), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:11</a>. ἐ. <span class=\"greek\">χρόνον</span> <span class=\"greek\">ἱκανόν</span>. Igualmente, ἐ. <span class=\"greek\">πολύ</span>, <i>por longo tempo, ao longo de extenso período</i> (Thu. 1, 7; 1, 18, 1; 2, 16, 1 e outros; Appian, Liby. 5 §21; Arrian, Cyneg. 23, 1; Lucian, Toxar. 20; Wsd 18:20; Sir 49:13; JosAs 19:3; Jos., Vi. 66; Just., A I, 65, 3), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:6</a>. ἐ. <span class=\"greek\">πλεῖον</span>, <i>o mesmo</i> (escólio a Pind., N. 7, 56b; PLille 3, 16 [século III a.C.]; Jdth 13:1; prólogo de Sir, linha 7; Jos., Ant. 18, 150), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:9</a>; <i>por mais tempo</i> (Lucian, D. Deor. 5, 3; Appian, Hann. 54 §227; 3 Macc 5:8; Wsd 8:12; Ath. 12, 3), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:4</a>; 1 Cl 55:1.</p></section></article>\n<article id=\"entry-epibaino-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβαίνω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epibaínō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐπιβήσομαι</span> (LXX); segundo aoristo <span class=\"greek\">ἐπέβην</span>; perfeito <span class=\"greek\">ἐπιβέβηκα</span> (ver <span class=\"greek\">βαίνω</span>; Hom.+; também Tat. 39, 1 [com genitivo]).</p>\n<p class=\"entry-text\"><b>① Mover-se para cima de alguma coisa; subir a, montar, embarcar.</b> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span> (Hdt. 8, 120; Thu. 1, 111, 2; 7, 69, 4; X., Hell. 3, 4, 1; SIG 709, 36 [107 a.C.]; em todas essas passagens trata-se de embarcar em navios. Gen 24:61, <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">καμήλους</span>; 1 Km 25:20, 42, <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὄνον</span>; Jos., Ant. 11, 258, <span class=\"greek\">ἐπὶ</span> τ. <span class=\"greek\">ἵππον</span>). <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ὄνον</span>, <i>sobre um jumento</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:5</a> (Zech 9:9; cf. Just., A I, 32, 6). <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θυσιαστήριον</span>, <i>ao altar</i>, GJs 5:1. <span class=\"greek\">πλοίῳ</span>, <i>num navio</i> (cf. Thu. 7, 70, 5, <span class=\"greek\">ταῖς</span> <span class=\"greek\">ναυσίν</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:2</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:6</a>, variante. Em emprego absoluto, <i>embarcar, subir a bordo</i> (Thu. 7, 62, 2), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:1</a> D, 2. Assim, talvez, também ἐ. <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἱεροσόλυμα</span>, <i>embarcar com destino a Jerusalém</i> (isto é, ao porto de Cesareia), v. 4. Mas essa passagem pode também pertencer à acepção ②.</p>\n<p class=\"entry-text\"><b>② Mover-se para determinada região e ali estar; pôr os pés em.</b> (Hom. e outros.) <span class=\"greek\">εἰς</span> τ. <span class=\"greek\">Ἀσίαν</span>, <i>pôr os pés na Ásia</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:18</a> (cf. Diod S 14, 84, 1, <span class=\"greek\">εἰς</span> τ. <span class=\"greek\">Βοιωτίαν</span>; POxy 1155, 3s. [104 d.C.], <span class=\"greek\">ἰς</span> <span class=\"greek\">Ἀλεξάνδρηαν</span>; PFlor 275, 22; ViJer 7, <span class=\"greek\">ἐν</span> <span class=\"greek\">Αἰγύπτῳ</span>; Just., D. 16, 2, <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Ἰερουσαλήμ</span>). Com dativo (Diod S 16, 66, 6), <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐπαρχείᾳ</span> (variante <span class=\"greek\">ἐπαρχείῳ</span>), <i>à província</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:1</a> (ver <span class=\"greek\">ἐπάρχειος</span>; cf. SIG 797, 16 [37 d.C.], <span class=\"greek\">ἐπιβὰς</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐπαρχείᾳ</span>). — M-M.</p></section></article>\n<article id=\"entry-epiballo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβάλλω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epibállō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">βάλλω</span>.) Futuro <span class=\"greek\">ἐπιβαλῶ</span> (LXX); segundo aoristo <span class=\"greek\">ἐπέβαλον</span>, terceira pessoa plural <span class=\"greek\">ἐπέβαλαν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:46</a> e <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:27</a>, variantes (W-S. §13, 13; Mlt-H. 208); perfeito, segunda pessoa singular <span class=\"greek\">ἐπιβέβληκας</span>, Ex 20:25. Passivo: futuro, terceira pessoa singular <span class=\"greek\">ἐπιβληθήσεται</span> (LXX); aoristo, terceira pessoa singular <span class=\"greek\">ἐπεβλήθη</span> (LXX). Hom.+.</p>\n<p class=\"entry-text\"><b>① Colocar sobre, transitivo, voz ativa.</b> <b>ⓐ Lançar por cima</b> <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span>, <i>algo sobre alguém</i>: <span class=\"greek\">βρόχον</span>, <i>um laço</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.35\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:35</a> (talvez em referência a uma rédea que manteria os que a usam sob controle: «manter-vos sob rédea curta», REB). <span class=\"greek\">τί</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:19</a>, variante.</p>\n<p class=\"entry-text\"><b>ⓑ Pôr sobre, colocar em cima.</b> <span class=\"greek\">ἱμάτιόν</span> <span class=\"greek\">τινι</span>, <i>uma veste sobre alguém</i> (Lev 19:19; Od. 14, 520, <span class=\"greek\">χλαῖναν</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:7</a>; sem dativo, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:50</a>, variante. <span class=\"greek\">τὴν</span> <span class=\"greek\">χεῖρα</span>, <i>pôr a mão</i> (Dt 15:10), <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span>, <i>sobre algo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.62\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:62</a>. <span class=\"greek\">τὰς</span> <span class=\"greek\">χεῖρας</span>, <i>as mãos</i>, <span class=\"greek\">τινί</span>, <i>sobre alguém, com violência</i> (Polyb. 3, 2, 8; 3, 5, 5; Lucian, Tim. 4; UPZ 106, 19 [99 a.C.]; Jos., Bell. 2, 491; Esth 6:2; Just., D. 95, 4), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:46</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:3</a>. Também <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> (PLeid G 19 [século II a.C.], H 26), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:50</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:19</a>; 21:12; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.44\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:44</a> (variante <span class=\"greek\">ἔβαλεν</span>); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:18</a>; 21:27 (Just., D. 93, 4, <span class=\"greek\">μέχρις</span> … <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>, <i>até mesmo sobre o Messias</i>). O singular τ. <span class=\"greek\">χεῖρα</span> nessa construção é raro (Aristoph., Nub. 933, Lysistr. 440; Gen 22:12; 2 Km 18:12): <i>ninguém pôs a mão nele</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:30</a>. ἐ. <span class=\"greek\">τὰς</span> <span class=\"greek\">χεῖρας</span> seguido de infinitivo de finalidade, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:1</a>; <span class=\"greek\">ἐπίβλημα</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ἱματίῳ</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:16</a>; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ἱμάτιον</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:36</a>.</p>\n<p class=\"entry-text\"><b>② Pôr-se a agir, intransitivo, voz ativa.</b> <b>ⓐ Lançar-se sobre ou irromper contra</b> (Pla., Phdr. 248a; Polyb. 5, 18, 3; 1 Macc 4:2); <i>arrebentar sobre</i>: <span class=\"greek\">τὰ</span> <span class=\"greek\">κύματα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλοῖον</span>, <i>as ondas arrebentavam sobre o barco</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:37</a>.</p>\n<p class=\"entry-text\"><b>ⓑ O sentido de <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπιβαλὼν</span> <span class=\"greek\">ἔκλαιεν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.72\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:72</a>, é incerto.</b> Teofilacto oferece uma alternativa entre <span class=\"greek\">ἐπικαλυψάμενος</span> τ. <span class=\"greek\">κεφαλήν</span> (assim ASchlatter, Zürcher Bibel 1931; Field, Notes 41–43; mas, nesse caso, dificilmente se poderia omitir <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱμάτιον</span>) e <span class=\"greek\">ἀρξάμενος</span>. Este último sentido é respaldado pela variante <span class=\"greek\">ἤρξατο</span> <span class=\"greek\">κλαίειν</span> e pode significar <i>começar</i> (PTebt 50, 12 [112/111 a.C.] <span class=\"greek\">ἐπιβαλὼν</span> <span class=\"greek\">συνέχωσεν</span>, <i>pôs mãos à obra e represou</i> [Mlt. 131s.]; Diogen. Cyn. em Diog. L. 6, 27, <span class=\"greek\">ἐπέβαλε</span> <span class=\"greek\">τερετίζειν</span>). A tradução seria então <i>e começou a chorar</i> (EKlostermann; OHoltzmann; JSchniewind; CCD; ver também B-D-F §308). Outros (BWeiss; HHoltzmann; 20th Cent.; Weymouth; L-S-J-M) partem das expressões ἐ. <span class=\"greek\">τὸν</span> <span class=\"greek\">νοῦν</span> ou <span class=\"greek\">τὴν</span> <span class=\"greek\">διάνοιαν</span> (Diod S 20, 43, 6) e do fato de que ἐ., por si só, usado com dativo, pode significar <i>pensar a respeito de</i> (M. Ant. 10, 30; Plut., Cic. 862 [4, 4]; Ath. 7, 1, <i>tratar de um problema</i>), chegando ao sentido <i>e pensou nisso</i>, ou <i>quando refletiu sobre isso</i>, a saber, sobre a predição de Jesus. Wlh. ad loc. argumentou contra essa posição, afirmando que ela se torna desnecessária pelo precedente <span class=\"greek\">ἀνεμνήσθη</span> <span class=\"greek\">κτλ</span>. Menos provável de todas é a equiparação de <span class=\"greek\">ἐπιβαλών</span> a <span class=\"greek\">ἀποκριθείς</span> (HEwald) com base em Polyb. 1, 80, 1; 22, 3, 8; Diod S 13, 28, 5, <span class=\"greek\">ἐπιβαλὼν</span> <span class=\"greek\">ἔφη</span>. Tanto a REB (<i>ele rompeu em lágrimas</i>) como a NRSV (<i>ele desabou e chorou</i>) captam o sentido. É provável que Marcos pretenda que o leitor imagine um gesto impetuoso associado ao lamento (ver EdeMartino, Morte e pianto rituale nel mondo antico, 1958, especialmente 195–235).</p>\n<p class=\"entry-text\"><b>③ Estar destinado à posse de alguém; caber a, pertencer a</b>, intransitivo, voz ativa; extensão da acepção ②: <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐπιβάλλον</span> <span class=\"greek\">μέρος</span>, <i>a parte que cabe a alguém</i> (Diod S 14, 17, 5; SIG 346, 36; 546 B, 19; 1106, 80; POxy 715, 13ss.; PFouad 25 verso I, 12s.; PFay 93, 8; cf. Tob 6:12; Ath., R. 49, 2, <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐπιβαλλούσης</span> <span class=\"greek\">ἑκάστῳ</span> <span class=\"greek\">χώρας</span>, <i>o lugar apropriado a cada qual</i> — Dssm., NB 57 [BS 230]), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:12</a> (JDerrett, Law in the NT 1970, 106). Impessoal, <span class=\"greek\">ἐπιβάλλει</span> <span class=\"greek\">τινί</span>, <i>alguém tem oportunidade</i> ou <i>convém a alguém</i> (Polyb. 18, 51, 1; OGI 443, 10; UPZ 110, 10 [164 a.C.], <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">ἐπιβάλλει</span>; Tob 3:17; Jos., Bell. 1, 434, Ant. 19, 6), Pol 1:1. Em <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:12</a>, <i>aquilo que me pertence</i>, «que me cabe».</p>\n<p class=\"entry-text\"><b>④ Aplicar-se com empenho a alguma coisa; assumir, empreender</b> (literalmente, <i>lançar-se sobre</i>), voz média com acusativo (Thu. 6, 40, 2; UPZ 41, 26 [161/160 a.C.], <span class=\"greek\">πᾶν</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">ἐπιβάλλησθε</span>; Just., D. 68, 1, com infinitivo): <span class=\"greek\">πρᾶξιν</span>, Hm 10, 2, 2; <span class=\"greek\">πολλά</span>, Hs 6, 3, 5. — M-M; TW.</p></section></article>\n<article id=\"entry-epibareo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβαρέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epibaréō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐπεβάρησα</span>. <b>Ser um peso para; sobrecarregar, pesar sobre.</b> (Dionys. Hal. 4, 9; 8, 73; Appian, Bell. Civ. 4, 15 §60; 4, 31 §133; Cyr. Ins. 8s.; SIG 807, 16 [c. 54 d.C.]; POxy 1481, 12 [século II d.C.]; POslo 60, 8.) <span class=\"greek\">τινά</span>, <i>alguém</i>; <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐπιβαρῆσαί</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ὑμῶν</span>, <i>para não ser pesado a nenhum de vós</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:9</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:8</a> (cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:9</a> e ver <span class=\"greek\">ἀβαρής</span>, <span class=\"greek\">καταβαρέω</span>; Paulo emula pessoas de espírito cívico que não desejavam onerar o público; ver a citação de SIG acima; cf. IGR III, 739, 30, 57s., do milionário Opramoas, <span class=\"greek\">μηδὲ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">βουλόμενος</span> <span class=\"greek\">βαρεῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔθνος</span>, <i>não desejando, nesse assunto, sobrecarregar o povo</i>). <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐπιβαρῶ</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:5</a>, parece ter o sentido de <i>para não acumular um peso excessivo de palavras</i>, isto é, <i>para não dizer demais</i> (Heinrici, Schmiedel, Ltzm., H-DWendland), embora não haja exemplos nesse sentido. Outras possibilidades: <i>exagerar</i>, <i>ser excessivamente severo</i>. Sobre o aspecto retórico, ver CClassen, WienerStud 107/108, 1994/95, 333. — DELG, s.v. <span class=\"greek\">βαρύς</span>; M-M.</p></section></article>\n<article id=\"entry-epibibazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβιβάζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epibibázō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐπιβιβῶ</span> (LXX); primeiro aoristo <span class=\"greek\">ἐπεβίβασα</span>. <b>Pôr alguém (<span class=\"greek\">τινά</span>) sobre alguma coisa; fazer alguém montar</b> (<span class=\"greek\">βιβάζω</span>, «fazer subir»; Thu. e outros; PCairZen 805, 4 [século III a.C.]; BGU 1742, 12; 1743, 9; Sb 9754, 12 [todos do século I a.C.]; LXX): <b>pôr em cima</b>; pôr Jesus <span class=\"greek\">ἐπὶ</span> τ. <span class=\"greek\">πῶλον</span>, <i>sobre o jumentinho</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:35</a> (cf. ET 42, 1931, 236s.; 288; 381s.; 382s.; 526s.); cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:24</a>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἴδιον</span> <span class=\"greek\">κτῆνος</span>, <i>alguém sobre seu próprio animal</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:34</a> (cf. 3 Km 1:33; mas ἐ. <span class=\"greek\">ἐπί</span> pode significar também <i>carregar sobre</i> [2 Km 6:3], supondo-se que o homem estivesse inconsciente). — DELG, s.v. <span class=\"greek\">βαίνω</span>.</p></section></article>\n<article id=\"entry-epiblepo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβλέπω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epiblépō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐπιβλέψω</span>, -<span class=\"greek\">ομαι</span> (LXX); primeiro aoristo <span class=\"greek\">ἐπέβλεψα</span> (TestJud 17:1; Just., D. 19:3, <span class=\"greek\">ἐπέβλεψεν</span> em lugar de <span class=\"greek\">ἐπεῖδεν</span> [Gen 4:4]). (Soph., Pla. e outros; LXX; PsSol 18:2; JosAs; ParJer 6:8; EpArist; Jos., Ant. 12, 58; Test12Patr; UPZ 78, 38 [159 a.C.]; Sb 7600, 5 [16 d.C.].)</p>\n<p class=\"entry-text\"><b>① Olhar fixamente; olhar, contemplar.</b> Acerca de Deus, <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἀβύσσοις</span>, <i>olhar nas profundezas</i>, 1 Cl 59:3 (cf. Sir 16:19; Da 3:55 Theod.); <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span>, <span class=\"greek\">τὸν</span> <span class=\"greek\">χείμαρρον</span>, GJs 18:2 (não em papiro). — Variante de <span class=\"greek\">ἐπισκέπτομαι</span>, GJs 1:4.</p>\n<p class=\"entry-text\"><b>② Prestar muita atenção a alguém, com implicação de deferência excessiva; mostrar respeito especial; fixar os olhos em.</b> <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:3</a>.</p>\n<p class=\"entry-text\"><b>③ Olhar atentamente, com implicação de interesse pessoal por alguém; olhar para.</b> Sobre o cuidado amoroso de Deus, que se volta para alguém ou algo (Ps.-Lucian, Astrol. 20; LXX; cf. Jos., Ant. 1, 20; PGM 13, 621): <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, 1 Cl 13:4 (Is 66:2); GJs 6:2. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span>: <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ταπείνωσιν</span>, <i>para a condição humilde</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:48</a> (cf. 1 Km 1:11; 9:16). Também sobre Jesus: <i>olhar para</i>, isto é, <i>interessar-se por</i>; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">υἱόν</span> <span class=\"greek\">μου</span>, <i>olha para meu filho</i>, com implicação de socorrê-lo, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:38</a>. — M-M.</p></section></article>\n<article id=\"entry-epiblema-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίβλημα, ατος, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epíblēma⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">βάλλω</span>; Nicostr. Com. 15; Plut., Arrian e outros; como peça de roupa usada para cobrir, já em SIG 1218, 4 [c. 420 a.C.], também Is 3:22; literalmente, «aquilo que é lançado por cima».) <b>Pedaço de tecido empregado para consertar um rasgo numa veste; remendo.</b> <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:16</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:21</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:36</a>. B-D-F §272. — M-M.</p></section></article>\n<article id=\"entry-epiboao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβοάω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epiboáō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">βοάω</span>.) Futuro, primeira pessoa plural, <span class=\"greek\">ἐπιβοήσομεν</span> (Just.). Voz ativa: Aeschyl., Thu. e outros; IG IV²/1, 742, 6 [séculos II/III d.C.]; 4 Macc 6:4; Just., A I, 68, 2. Voz média: BGU VIII, 1762, 3 [século I a.C.]. <b>Proferir uma expressão em voz alta; gritar em voz alta</b> (Heraclit. Sto. 6 p. 9, 15); de uma multidão agitada (Jos., Bell. 4, 283, <span class=\"greek\">ἐπεβόα</span> <span class=\"greek\">πλῆθος</span>; Ant. 11, 57): <b>berrar, gritar.</b> <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:24</a>, variante de leitura; MPol 3:2; 12:2s. — DELG, s.v. <span class=\"greek\">βοή</span>; M-M.</p></section></article>\n<article id=\"entry-epiboule-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβουλή, ῆς, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epiboulḗ⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">βουλή</span>; Hdt., Thu. e outros; UPZ 8, 14 [161 a.C.]; BGU 1816, 12 [60/59 a.C.]; POxy 237 VI, 6; 31; Sb 7464, 16; 9534, 5; LXX; TestBenj 3:5; ApcrEzk [Epiph. 70, 7]; Philo, Joseph.) <b>Plano secreto para realizar algo mau ou provocar dano; trama, conspiração.</b> <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span>, <i>contra alguém</i> (Jos., Ant. 2, 197; 16, 319), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:30</a>; também com dativo <span class=\"greek\">τινί</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:3</a>. ἡ ἐ. <span class=\"greek\">αὐτῶν</span>, <i>a trama deles</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:24</a>. Plural (Epict. 1, 22, 14; 1 Esdr 5:70; 2 Macc 8:7, variante): <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> ἐ. <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰουδαίων</span>, <i>por meio das tramas dos judeus</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:19</a>. — DELG, s.v. <span class=\"greek\">βούλομαι</span>; M-M.</p></section></article>\n<article id=\"entry-epigambreuo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγαμβρεύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epigambreúō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(<span class=\"greek\">γαμβρεύω</span>, «estabelecer vínculo pelo casamento».) Futuro <span class=\"greek\">ἐπιγαμβρεύσω</span>; primeiro aoristo <span class=\"greek\">ἐπεγάμβρευσα</span>. <b>Tornar-se parente por casamento</b> (escólios a Eur., Orest. 585–604, Phoen. 347; LXX); daí, <b>casar-se na condição de parente mais próximo</b>, normalmente de cunhado, no casamento levirático: <span class=\"greek\">γυναῖκα</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:24</a> (Dt 25:5 Aq.; cf. Gen 38:8, variante [ARahlfs, Genesis 1926, 159]; TestJud 10:4, «dar o cunhado da viúva como marido»; invertido na versão armênia). Sobre a palavra, ver Anz 378; sobre a ideia, KRengstorf, Jebamot 1929. — DELG, s.v. <span class=\"greek\">γαμβρός</span>; M-M.</p></section></article>\n<article id=\"entry-epigeios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίγειος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epígeios⟧</span><span class=\"separator\">·</span><span>adjetivo; substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Pla. e outros; TestSol; TestAbr A 4, 81, 18 [Stone p. 10]; Philo; Jos., Ant. 6, 186; 8, 44; Just., A II, 5, 2; Tat. 32, 1; Mel., P. 39; Ath.)</p>\n<p class=\"entry-text\"><b>① Pertencente ao que é característico da terra em contraste com o celestial; terrestre, terreno.</b> <b>ⓐ Como adjetivo.</b> (Plut., Mor. 566d; M. Ant. 6, 30, 4, ἐ. <span class=\"greek\">ζωή</span>; papiros; TestJud 21:4; Ath. 31, 3, <span class=\"greek\">βίον</span>.) <span class=\"greek\">σῶμα</span>, <i>corpo terrestre</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.40\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:40</a> (em oposição a <span class=\"greek\">ἐπουράνιος</span>; sobre esse contraste, ver adiante 1bα e MDahl, Resurrection of the Body 1962, 113–16). Do corpo: <span class=\"greek\">οἰκία</span> ἐ., <i>habitação terrena</i> (cf. Philo, Cher. 101), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:1</a> (EEllis, Paul and His Recent Interpreters 1961, 40–43). Com conotação de fraqueza (Lucian, Icarom. 2): <span class=\"greek\">σοφία</span>, <i>sabedoria terrena</i>, isto é, filosofia humana, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:15</a> (cf. Ath. 24, 5 [contexto mutilado]); cf. <span class=\"greek\">εὕρημα</span> ἐ., <i>descoberta terrena</i>, isto é, puramente humana, Dg 7:1. <span class=\"greek\">πνεῦμα</span> ἐ., <i>espírito terreno</i>, do espírito dos falsos profetas, Hm 9:11; 11:6, 11s., 14, 17, 19 (cf. Tat. 32, 1, <span class=\"greek\">λόγου</span> <span class=\"greek\">τοῦ</span> … ἐ.).</p>\n<p class=\"entry-text\"><b>ⓑ Como substantivo.</b> <b>α. <span class=\"greek\">τὰ</span> ἐ., as coisas terrenas.</b> (M. Ant. 7, 48; Philo, Op. M. 101; 113; Just., A II, 5, 2; Ath. 27, 1 [ambos em oposição a <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπουράνια</span>]. — Também em oposição a <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπουράνια</span>, como Herm. Wr. Fgm. 26 p. 544, 1 Sc.; cf. Philo, Op. M. 117; Mel., P. 39.) <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:12</a> (LBrun, SymbOsl 8, 1929, 57–77); cf. Pol 2:1; Dg 7:2.</p>\n<p class=\"entry-text\"><b>β. <span class=\"greek\">οἱ</span> ἐ., os seres terrestres.</b> Na expressão <span class=\"greek\">πᾶν</span> <span class=\"greek\">γόνυ</span> <span class=\"greek\">ἐπουρανίων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπιγείων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">καταχθονίων</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:10</a>, o segundo dos três conceitos principais não se limita aos seres humanos (cf. PGM 4, 225s.; 3038ss., esp. 3042s., <span class=\"greek\">πᾶν</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">δαιμόνιον</span> … <span class=\"greek\">ἐπουράνιον</span> ἢ <span class=\"greek\">ἀέριον</span> <span class=\"greek\">εἴτε</span> <span class=\"greek\">ἐπίγειον</span> <span class=\"greek\">εἴτε</span> <span class=\"greek\">ὑπόγειον</span> ἢ <span class=\"greek\">καταχθόνιον</span>; 5, 166s., <span class=\"greek\">πᾶς</span> <span class=\"greek\">δαίμων</span> <span class=\"greek\">οὐράνιος</span> κ. <span class=\"greek\">αἰθέριος</span> κ. <span class=\"greek\">ἐπίγειος</span> κ. <span class=\"greek\">ὑπόγειος</span>; 12, 67, <span class=\"greek\">θεοὶ</span> <span class=\"greek\">οὐράνιοι</span> κ. <span class=\"greek\">ἐπίγειοι</span> κ. <span class=\"greek\">ἀέριοι</span> κ. <span class=\"greek\">ἐπιχθόνιοι</span>; 17a, 3, <span class=\"greek\">Ἄνουβι</span>, <span class=\"greek\">θεὲ</span> <span class=\"greek\">ἐπίγειε</span> κ. <span class=\"greek\">ὑπόγειε</span> κ. <span class=\"greek\">οὐράνιε</span>; IDefixWünsch 4, 11; TestSol); cf. ITr 9:1. Em IEph 13:2 não é possível determinar com certeza de qual nominativo provém <span class=\"greek\">ἐπιγείων</span>: <span class=\"greek\">ἐπίγειοι</span> ou <span class=\"greek\">ἐπίγεια</span>.</p>\n<p class=\"entry-text\"><b>② Relativo às coisas terrenas, com implicação de satisfação pessoal;</b> substantivado, <b>coisas mundanas.</b> <span class=\"greek\">τὰ</span> ἐ. <span class=\"greek\">φρονεῖν</span>, <i>pensar somente nas coisas mundanas</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:19</a>. — DELG, s.v. <span class=\"greek\">γῆ</span>; M-M; TW.</p></section></article>\n<article id=\"entry-epigelao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγελάω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epigeláō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐπιγελάσομαι</span> (ver <span class=\"greek\">γελάω</span>; Pla., X. e outros; LXX; Just., D. 139, 1). <b>Rir de, zombar de</b> <span class=\"greek\">τινί</span>, <i>algo</i> (Jos., Bell. 1, 233, <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἐλπίσιν</span>): ἐ. <span class=\"greek\">τῇ</span> <span class=\"greek\">ὑμετέρᾳ</span> <span class=\"greek\">ἀπωλείᾳ</span>, <i>rir de vossa destruição</i>, 1 Cl 57:4 (Pr 1:26).</p></section></article>\n<article id=\"entry-epiginomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγίνομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epigínomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Segundo aoristo <span class=\"greek\">ἐπεγενόμην</span> (ver <span class=\"greek\">γίνομαι</span>; em vários sentidos, mas em geral de algo que acontece em seguida; Hom. e outros; inscrições, papiros, LXX; TestSol 9:8 L, por <span class=\"greek\">παραγίνομαι</span>; Philo, Aet. M. 20 e outros). <b>Acontecer, implicando o surgimento de nova condição; ocorrer, sobrevir.</b> Do vento, <i>levantar-se</i> (Thu. 3, 74, 2; 4, 30, 2; Diod S 18, 20, 7, <span class=\"greek\">ἐπιγενομένου</span> <span class=\"greek\">μεγάλου</span> <span class=\"greek\">πνεύματος</span>; Jos., Ant. 9, 209), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:13</a>. Da noite, <i>cair, sobrevir</i> (Hdt. 8, 70 e outros; Arrian, Anab. 1, 2, 7, <span class=\"greek\">νὺξ</span> <span class=\"greek\">ἐπιγενομένη</span>; 2, 11, 5; Polyaenus 3, 7, 3 e outros; Jos., Ant. 1, 301), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:27</a>, variante. — DELG, s.v. <span class=\"greek\">γίγνομαι</span>; M-M.</p></section></article>\n<article id=\"entry-epiginosko-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγινώσκω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epiginṓskō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐπιγνώσομαι</span>; segundo aoristo <span class=\"greek\">ἐπέγνων</span>; perfeito <span class=\"greek\">ἐπέγνωκα</span>; primeiro aoristo passivo <span class=\"greek\">ἐπεγνώσθην</span> (Hom.+). Em geral, <b>conhecer, compreender, reconhecer.</b></p>\n<p class=\"entry-text\"><b>① Ter conhecimento de algo ou alguém; conhecer.</b> <b>ⓐ Com influência perceptível do prefixo:</b> <i>conhecer exata, completa e profundamente</i>, <span class=\"greek\">τὶ</span>, <i>algo</i> (Jos., Ant. 20, 128, τ. <span class=\"greek\">ἀλήθειαν</span>), τ. <span class=\"greek\">ἀσφάλειαν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:4</a>; τ. <span class=\"greek\">δικαίωμα</span> τ. <span class=\"greek\">θεοῦ</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:32</a>; τ. <span class=\"greek\">χάριν</span> τ. <span class=\"greek\">θεοῦ</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:6</a> (aqui ἐ. é o segundo estágio após <span class=\"greek\">ἀκούειν</span>; cf. IEph 4:2). Absoluto, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:12a</a> (em oposição a <span class=\"greek\">γινώσκειν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">μέρους</span>); PtK 3 p. 15, 27. Com oração relativa seguinte, Dg 11:7. Passivo, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:12b</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:9</a>.</p>\n<p class=\"entry-text\"><b>ⓑ Sem ênfase no prefixo:</b> essencialmente igual a <span class=\"greek\">γινώσκειν</span> (X., Hell. 5, 4, 12, cf. 6, 5, 17; Thu. 1, 132, 5; SIG 741, 21; 747, 30; PFay 112, 14; PTebt 297, 9 e outros; EpArist 246; SibOr 3, 96). <i>Conhecer</i>, absoluto, Dg 10:3; 12:6. <span class=\"greek\">τινά</span>, <i>alguém</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:27</a> (o paralelo em <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:22</a> tem o verbo simples <span class=\"greek\">γιν</span>.; ver <span class=\"greek\">παραδίδωμι</span> 3, fim); 14:35; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.54\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:54</a>; Hv 5:3. EpilMosq 3, ver ④ abaixo. Dg 10:1 (conjectura de Nock; ver edição de Marrou). <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span>, B 10:3 (Is 1:3). ὁ <span class=\"greek\">δὲ</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἐπιγνούς</span>, Hs 9, 18, 1. <span class=\"greek\">τί</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:39</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀλήθειαν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:3</a>; cf. 1 Cl 32:1 (Just., D. 110, 6); Hs 8, 6, 3; 8, 11, 2; Dg 10:8. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, <i>conhecer alguém por meio de algo</i> (cf. Sir 19:29), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:16</a>, 20 (o paralelo em <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:44</a> tem a forma simples). ἐ. <span class=\"greek\">μέλη</span> <span class=\"greek\">ὄντας</span>, <i>reconhecer que sois membros</i>, IEph 4:2. <span class=\"greek\">ἐπιγνοὺς</span> <span class=\"greek\">ἐνάρετον</span> … <span class=\"greek\">οὖσαν</span>, <i>ao perceber quão nobre é (a mente do supervisor/bispo)</i>, IPhld 1:2 (de modo semelhante, com particípio, Just., D. 58, 3, <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ὑπηρετοῦντα</span>). Seguido de <span class=\"greek\">ὅτι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:34</a> (En 98:8; Just., D. 51, 3 e outros). Seguido de acusativo e <span class=\"greek\">ὅτι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.37\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:37</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:5</a>; Hv 5:4. Passivo, seguido de interrogação indireta, Hs 4:3.</p>\n<p class=\"entry-text\"><b>② Verificar ou obter informação a respeito de algo</b>, sem ênfase no prefixo. <b>ⓐ Aprender, descobrir.</b> (Jos., Vi. 181.) Emprego absoluto, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:33</a> (variante <span class=\"greek\">ἔγνωσαν</span>). Seguido de <span class=\"greek\">ὅτι</span> (1 Macc 6:17), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:37</a>; 23:7; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:29</a>; 28:1. <b>ⓑ Passar a conhecer.</b> Absoluto, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:21b</a>; <span class=\"greek\">τὶ</span>, <i>algo</i> (Herodian 2, 1, 10), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:21a</a>; Hm 6, 2, 6; Hs 9, 16, 7; PtK 4 p. 16, 1. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, <i>a respeito de alguém</i>, IRo 10:2. <b>ⓒ Notar, perceber, tomar conhecimento de, verificar.</b> Absoluto, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:30</a> (Field, Notes 117s.); <span class=\"greek\">τὶ</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:22</a>; <span class=\"greek\">τὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτῷ</span>, <i>perceber algo dentro de si</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:30</a> (o paralelo <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:46</a> tem o verbo simples). Seguido de <span class=\"greek\">ὅτι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:22</a>; ἐ. <span class=\"greek\">τῷ</span> <span class=\"greek\">πνεύματι</span>, <span class=\"greek\">ὅτι</span>, <i>perceber em seu próprio espírito que</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:8</a>. Também como termo técnico jurídico, <i>verificar</i> (2 Macc 14:9), <span class=\"greek\">τὶ</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:28</a>; cf. 24:8. Seguido de <span class=\"greek\">ὅτι</span>, 24:11; de oração relativa, 22:24.</p>\n<p class=\"entry-text\"><b>③ Relacionar informação ou percepção presente com algo anteriormente conhecido; reconhecer alguém, identificar, tornar a conhecer</b> <span class=\"greek\">τινά</span>, <i>alguém</i>, com influência perceptível do prefixo, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:16</a>, 31 (TestJob 28:3; Just., D. 40, 4; sobre a autorrevelação na cultura grega, cf. GMost, JHS 109, 1989, 114–33). <span class=\"greek\">τὶ</span>, <i>algo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:14</a> (τ. <span class=\"greek\">φωνήν</span> <span class=\"greek\">τινος</span>, como 1 Km 26:17; Judg 18:3 A). Com acusativo de pessoa e <span class=\"greek\">ὅτι</span> seguinte, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:10</a>; 4:13.</p>\n<p class=\"entry-text\"><b>④ Indicar que se valoriza a pessoa de outro; reconhecer, dar reconhecimento a</b> <span class=\"greek\">τινά</span>, <i>alguém</i>, com influência perceptível do prefixo (Chion, Ep. 6; Ruth 2:10, 19), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:12</a> (também é provável o sentido ③); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:18</a> (Just., D. 29, 2; 45, 4 e outros). EpilMosq 3 (num jogo de palavras, devendo entender-se a resposta de Policarpo no sentido de ①ⓑ).</p>\n<p class=\"entry-text\"><b>⑤ Chegar à compreensão de algo; compreender, conhecer</b> <span class=\"greek\">τὶ</span> ou <span class=\"greek\">τινά</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:13s</a>. (aqui o intensificador <span class=\"greek\">ἕως</span> <span class=\"greek\">τέλους</span> faz ἐ. equivaler ao verbo simples <span class=\"greek\">γιν</span>.; note-se também os qualificadores que seguem na voz passiva). <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀληθῶς</span> <span class=\"greek\">ζῆν</span>, <i>conhecer a verdadeira vida</i>, Dg 10:7. <span class=\"greek\">σὺ</span> <span class=\"greek\">κάλλιον</span> <span class=\"greek\">ἐπιγινώσκεις</span>, <i>tu sabes muito bem</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:10</a> (a influência do advérbio faz o composto equivaler ao verbo simples, como PLond II, 354, 24 p. 165 [c. 10 a.C.], <span class=\"greek\">ἐπιγνόντα</span> <span class=\"greek\">ἀκρειβῶς</span> <span class=\"greek\">ἕκαστα</span>; Just., D. 96, 2, <span class=\"greek\">μᾶλλον</span>). — DELG, s.v. <span class=\"greek\">γιγνώσκω</span>; M-M; TW.</p></section></article>\n<article id=\"entry-epignosis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίγνωσις, εως, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epígnōsis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">γνῶσις</span> e o verbete anterior; Philo, Mech. 59, 2; Polyb. 3, 7, 6; 3, 31, 4; Diod S 3, 38, 2; Epict. 2, 20, 21; Plut., Mor. 1145a; Herodian 7, 6, 7; papiros [Mayser 438; UPZ 118, 16: 136 a.C.?; BGU 1873, 20s.; PTebt 28, 11: c. 114 a.C.]; LXX, EpArist, Philo, Just., Tat.; <span class=\"greek\">καιρῶν</span> ἐ., Did., Gen. 195, 28.) <b>Conhecimento, reconhecimento</b>; em nossa literatura, limitado a questões transcendentes e morais (Hierocles 22 p. 467).</p>\n<p class=\"entry-text\">Com genitivo da coisa conhecida (Diod S 3, 56, 5, <span class=\"greek\">τῶν</span> <span class=\"greek\">ἄστρων</span> ἐ.): <span class=\"greek\">δόξης</span> <span class=\"greek\">ὀνόματος</span> <span class=\"greek\">αὐτοῦ</span>, 1 Cl 59:2 (ali <span class=\"greek\">ἀγνωσία</span> contrasta com <span class=\"greek\">ἐπίγν</span>.). (<span class=\"greek\">τῆς</span>) <span class=\"greek\">ἀληθείας</span>, <i>conhecimento da verdade</i> (Epict. 2, 20, 21; Philo, Omn. Pr. L. 74; <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀληθοῦς</span>, Just., D. 3, 4. — MDibelius, <span class=\"greek\">Ἐπίγνωσις</span> <span class=\"greek\">ἀληθείας</span>: GHeinrici Festschr. 1914, 178–89), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:4</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:25</a>; 3:7; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:1</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:26</a> (sobre a expressão <span class=\"greek\">εἰς</span> <span class=\"greek\">ἐπίγνωσιν</span> <span class=\"greek\">ἔρχεσθαι</span> em <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:4</a> e <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:7</a>, cf. 2 Macc 9:11). <span class=\"greek\">ἁμαρτίας</span>, <i>consciência do pecado</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:20</a>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">μυστηρίου</span> τ. <span class=\"greek\">θεοῦ</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:2</a>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θελήματος</span> <span class=\"greek\">αὐτοῦ</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:9</a>. <span class=\"greek\">παντὸς</span> <span class=\"greek\">ἀγαθοῦ</span>, Phlm 6 (cf. Herm. Wr. 3, 3b, <span class=\"greek\">ἀγαθῶν</span> ἐ.; EpArist 139; ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">καλοῦ</span>, Did., Gen. 72, 17).</p>\n<p class=\"entry-text\">Com genitivo da pessoa conhecida: ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, <i>conhecimento de Deus</i> (Pr 2:5; Hos 4:1; Just., A II, 10, 6; Tat. 13, 1), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:10</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:2</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:17</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:3</a>; Dg 10:1. Também ἡ <span class=\"greek\">περί</span> <span class=\"greek\">σου</span> ἐ., MPol 14:1; ἐ. <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:13</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:8</a>; 2:20. Conhecimento de Deus e de Cristo, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:2</a>; mas talvez se reflita aqui a terminologia jurídica (=cognitio; cf. PTebt 28, 11, <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἕκαστα</span> <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">ἐπίγνωσιν</span> <span class=\"greek\">ἀχθῆναι</span> [114 a.C.]; SIG 826d, 16s.).</p>\n<p class=\"entry-text\">Emprego absoluto (cf. Hos 4:6): <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ἐν</span> ἐ., <i>reconhecer Deus</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:28</a>; com <span class=\"greek\">αἴσθησις</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:9</a>; <span class=\"greek\">ἀνακαινούμενος</span> <span class=\"greek\">εἰς</span> ἐ., <i>renovado em conhecimento</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:10</a>. <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐπίγνωσιν</span>, <i>segundo o (verdadeiro) conhecimento</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:2</a>. — DELG, s.v. <span class=\"greek\">γιγνώσκω</span>; M-M; TW.</p></section></article>\n<article id=\"entry-epigraphe-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγραφή, ῆς, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epigraphḗ⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">γραφή</span>; Thu. e outros; inscrições, papiros; TestSol 18:22 P; Philo; Jos., Ant. 15, 272; Just., A I, 26, 2.) Normalmente designa documento gravado em pedra, mas também inscrições identificadoras em materiais de qualquer espécie: <b>inscrição, sobrescrito.</b> Da inscrição de identificação (<i>titulus</i>) afixada a uma cruz (cf. Sueton., Calig. 32, Domit. 10; Cass. Dio 54, 3; Eus., HE 5, 1, 44): ἐ. <span class=\"greek\">τῆς</span> <span class=\"greek\">αἰτίας</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:26</a>. <span class=\"greek\">ἦν</span> ἐ. <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτῷ</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:38</a>. Das legendas em moedas, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:20</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:16</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:24</a>. — DELG, s.v. <span class=\"greek\">γράφω</span>; M-M.</p></section></article>"};
